def detect_correction(query):
    keywords = ['not ', 'is ', 'wrong', 'correct', 'should be']
    return any(kw in query.lower() for kw in keywords)

def store_correction_if_found(query):
    if not detect_correction(query):
        return
    try:
        if ' not ' in query.lower():
            parts = query.lower().split(' not ')
            if len(parts) == 2:
                wrong = parts[0].strip()
                right = parts[1].strip()
                db.execute("""INSERT INTO corrections
                              (incorrect_text, correct_text, context, category, created_at)
                              VALUES (?, ?, 'he corrected me in chat', 'chat',
                                      CURRENT_TIMESTAMP)""", (wrong, right))
                if db.query("SELECT id FROM corrections WHERE incorrect_text = ? "
                            "ORDER BY id DESC LIMIT 1", (wrong,)):
                    print("LEARNED: " + wrong + " -> " + right)
                else:
                    print("correction did NOT save: " + wrong)
    except Exception as _ec:
        print("correction failed: " + str(_ec)[:70])


def get_current_time_context():
    """Get current time in Freetown and Charlie's current location"""
    from datetime import datetime
    import pytz
    
    # Get Charlie's current timezone from database
    tz_data = db.query("SELECT charlie_current_timezone FROM timezone_tracking LIMIT 1")
    charlie_tz_name = tz_data[0]['charlie_current_timezone'] if tz_data else 'Africa/Nairobi'
    
    freetown_tz = pytz.timezone('Africa/Freetown')
    charlie_tz = pytz.timezone(charlie_tz_name)
    
    freetown_time = datetime.now(freetown_tz).strftime('%I:%M %p %Z')
    charlie_time = datetime.now(charlie_tz).strftime('%I:%M %p %Z')

    # she must never guess the day
    from datetime import timedelta as _td
    _n = datetime.now(charlie_tz)
    _datebit = ("TODAY IS " + _n.strftime('%A %-d %B %Y') +
                ". Tomorrow is " + (_n + _td(days=1)).strftime('%A %-d %B') +
                ", yesterday was " + (_n - _td(days=1)).strftime('%A %-d %B') +
                ". Work every date out from that - never guess the day or the date.\n")
    
    # If Charlie is in Freetown, just show one time
    if charlie_tz_name == 'Africa/Freetown':
        return _datebit + f"Current time in Freetown: {freetown_time} (we're on the same time!)"
    else:
        return _datebit + f"Time: {charlie_time} where Charlie is, {freetown_time} in Freetown."



