            if nice_do:
                response += "🟡 **NICE TO DO** (" + str(len(nice_do)) + "):\n"
                for t in nice_do:
                    energy_emoji = '🟢' if t[4] == 'low' else '🟡' if t[4] == 'medium' else '🔴'
                    status = '✅' if t[2] == 'done' else '❌'
                    response += f"  {status} {t[1]} {energy_emoji}\n"
                response += "\n"
            
            if stretch:
                response += "🟢 **STRETCH** (" + str(len(stretch)) + "):\n"
                for t in stretch:
                    energy_emoji = '🟢' if t[4] == 'low' else '🟡' if t[4] == 'medium' else '🔴'
                    status = '✅' if t[2] == 'done' else '❌'
