    try:
        cur = (request.args.get('currency') or 'USD').upper()
        rate, source, when = _fx_rate(cur)
        return {"status": "success", "currency": cur, "rate_to_usd": rate,
                "source": source, "date": when}
    except Exception as e:
        return {"error": str(e)}, 400


