@app.get("/api/prices/overview")
@require_password
def prices_overview():
    """Everything he has in more than one place, so he can see where life is dearer."""
    try:
        rows = db.query("""SELECT item_name, country, city, per_unit_usd, observed_on,
                                  standard_unit, local_price, currency
                           FROM price_entries WHERE per_unit_usd IS NOT NULL""") or []
        byitem = {}
        for r in rows:
            byitem.setdefault(r['item_name'], {}).setdefault(r.get('country') or r.get('city') or '?', []).append(r)
        out = []
        for item, places in byitem.items():
            if len(places) < 2:
                continue
            cells = []
            for place, rs in places.items():
                st = _stats(rs)
                if st:
                    st['where'] = place
                    st['confidence'] = _confidence(st)
                    cells.append(st)
            if len(cells) < 2:
                continue
            cells.sort(key=lambda c: c['median'])
            spread = (round((cells[-1]['median'] - cells[0]['median']) / cells[0]['median'] * 100)
                      if cells[0]['median'] else 0)
            out.append({"item": item, "unit": rows[0].get('standard_unit'),
                        "cheapest": cells[0]['where'], "dearest": cells[-1]['where'],
                        "spread_pct": spread, "places": cells})
        out.sort(key=lambda x: -x['spread_pct'])
        return {"status": "success", "items": out}
    except Exception as e:
        return {"error": str(e)}, 400


def _instant_lookup(text):
    """A number or a stored fact, straight from the database. None = let Ami handle it."""
    import re as _r
    low = (text or '').strip().lower().rstrip('?.! ')
    if not low or len(low) > 90:
        return None

    # --- how many of something have I done today -------------------------
    m = _r.search(r"how many ([a-z\- ]{3,20}?)s? (have i|did i|i)\s*(done|did|do)?"
                  r"\s*(today|so far|this morning)?$", low)
    if m:
        what = m.group(1).strip().rstrip('s')
        try:
            rows = db.query("""SELECT g.name, g.target,
                                      COALESCE(SUM(l.amount), 0) AS done
                               FROM fitness_goals g
                               LEFT JOIN goal_log l
                                 ON l.goal_id = g.id AND l.done_on = date('now')
                               WHERE g.active = 1 AND LOWER(g.name) LIKE ?
                               GROUP BY g.id""", ('%' + what + '%',))
            if rows:
                g = rows[0]
                d, t = int(g['done'] or 0), int(g['target'] or 0)
                if d == 0:
                    return "None yet today, bo. " + str(t) + " " + g['name'].lower() + " to go."
                if t and d >= t:
                    return (g['name'] + ": " + str(d) + " of " + str(t) + " - yu don finish am. "
                            "\U0001F4AA")
                return (g['name'] + ": " + str(d) + " of " + str(t) + " so far. "
                        + str(t - d) + " left.")
        except Exception:
            pass

    # --- how much is X / what did I pay for X ----------------------------
    m = _r.search(r"(?:how much (?:is|was|did i pay for)|what did i pay for|"
                  r"what(?:'s| is) the price of)\s+([a-z][a-z \-]{1,24})$", low)
    if m:
        item = m.group(1).strip()
        try:
            rows = db.query("""SELECT item_name, local_price, currency, city, country,
                                      usd_price, observed_on
                               FROM price_entries
                               WHERE LOWER(item_name) LIKE ?
                               ORDER BY observed_on DESC LIMIT 3""", ('%' + item + '%',))
            if rows:
                bits = []
                for r0 in rows:
                    where = r0.get('city') or r0.get('country') or ''
                    bits.append(str(r0['local_price']).rstrip('0').rstrip('.') + " "
                                + str(r0['currency'] or '')
                                + (" for " + where if where else "")
                                + (" ($" + str(round(r0['usd_price'], 2)) + ")"
                                   if r0.get('usd_price') else "")
                                + " on " + str(r0['observed_on'])[:10])
                return rows[0]['item_name'] + ": " + "; ".join(bits) + "."
            return "A no get any price for " + item + " inside mi list yet, bo."
        except Exception:
            pass

    # --- how many tasks / todos / reminders do I have ---------------------
    m = _r.search(r"how many (tasks?|todos?|to-?dos?|reminders?)"
                  r"(?: do i have| have i got| dey| left)?$", low)
    if m:
        kind = m.group(1).rstrip('s').replace('-', '')
        try:
            if kind.startswith('task'):
                n = db.query("SELECT COUNT(*) c FROM tasks "
                             "WHERE status NOT IN ('done','cancelled','completed')")
                return str(n[0]['c']) + " tasks still open, bo."
            if kind.startswith('todo'):
                n = db.query("SELECT COUNT(*) c FROM todos WHERE status = 'pending'")
                return str(n[0]['c']) + " todos waiting."
            n = db.query("SELECT COUNT(*) c FROM reminders "
                         "WHERE status != 'completed' AND due_date >= date('now')")
            return str(n[0]['c']) + " reminders coming up."
        except Exception:
            pass

    # --- how much have I spent on the API ---------------------------------
    if _r.search(r"(api|gemini) (cost|spend|spent|bill)|how much.*(api|gemini)", low):
        try:
            r0 = db.query("""SELECT ROUND(COALESCE(SUM(est_cost),0),2) t,
                                    COUNT(*) n FROM api_usage_logs
                             WHERE DATE(created_at) = date('now')""")
            r1 = db.query("""SELECT ROUND(COALESCE(SUM(est_cost),0),2) t
                             FROM api_usage_logs
                             WHERE created_at >= date('now','start of month')""")
            return ("$" + str(r0[0]['t']) + " today across " + str(r0[0]['n'])
                    + " calls, $" + str(r1[0]['t']) + " this month.")
        except Exception:
            pass

    # --- how much water -----------------------------------------------------
    if _r.search(r"how much water|water (so far|today|left)", low):
        try:
            r0 = db.query("""SELECT COALESCE(SUM(litres),0) l FROM water_log
                             WHERE logged_on = date('now')""")
            got = round(float(r0[0]['l'] or 0), 2)
            tgt = 2.7
            try:
                t0 = db.query("SELECT value FROM charlie_profile WHERE key='water_target'")
                if t0:
                    tgt = float(t0[0]['value'])
            except Exception:
                pass
            if got >= tgt:
                return str(got) + "L down - yu don pass di target. \U0001F4A7"
            return (str(got) + "L of " + str(tgt) + "L so far. "
                    + str(round(tgt - got, 2)) + "L to go.")
        except Exception:
            pass

    return None


def _maybe_make_project(query, session_id=None):
    """He said "do it" after she laid out a plan. Make the project, propose the
    tasks, and tell him where to tick them. Returns a reply or None."""
    import re as _r
    low = (query or '').strip().lower().rstrip('.!')
    if len(low) > 70:
        return None
    if not _r.search(r"^(ok(ay)?,? )?(yes,? )?(can you |could you |please )?(lets?|let us|go|do|set|make|create|build|start|add|put|save|track)\b.{0,60}$", low):
        return None
    if not _r.search(r"\b(do it|set (it|that) up|make (it|that|the project)|create (it|that|the project)|lets do it|go ahead|build it|start it|set up the project|add the project|make the project|add (this|that|it|them|those|all)\b|add the (whole|entire|full)|put (this|that|them)\b|track (this|that|it)|save (this|that|it))", low):
        return None

    # what was she just talking about?
    rows = db.query("""SELECT user_message, ami_response FROM conversations
                       WHERE DATE(timestamp) >= date('now','-1 day')
                       ORDER BY id DESC LIMIT 14""") or []
    plan, idea = None, None
    for r in rows:
        resp = str(r.get('ami_response') or '')
        # a substantial reply of hers about something he raised is the plan.
        # do not insist it uses the word "phase" - she rarely does.
        # skip her own asking-back and her refusals - they are not plans
        if _r.search(r"which one|tell mi|a no get|a no fit|wetin yu mean", resp.lower()):
            continue
        # and skip the very message he is answering with
        if _r.search(r"\\b(add|do it|set it up|track|save)\\b",
                     str(r.get('user_message') or '').lower()) and len(resp) < 700:
            continue
        if len(resp) > 300 and len(str(r.get('user_message') or '')) > 20:
            plan = resp
            idea = str(r.get('user_message') or '')
            break
    if not plan:
        return None

    # a name for it
    try:
        import google.genai as genai
        client = genai.Client()
        resp = gemini_guard() or note_gemini_call() or _ask_gemini(
            client, prompt=("Charlie asked for this:\n" + idea[:400] +
                            "\n\nGive it a short project name - two to four words, no "
                            "quotes, no punctuation, nothing else. Just the name."))
        note_gemini_tokens(resp)
        name = (resp.text or '').strip().strip('"\'').split(chr(10))[0][:60]
    except Exception:
        name = (idea[:40] or 'New project').strip()
    if len(name) < 3:
        return None

    # make it, and propose the tasks
    try:
        with app.test_request_context(
                '/api/projects/create', method='POST',
                json={"name": name, "about": idea[:400], "plan": plan[:2500]},
                headers={'X-Ami-Password': AMI_PASSWORD}):
            out = project_create()
        d = out[0] if isinstance(out, tuple) else out
        if not isinstance(d, dict) or d.get('error'):
            return None
    except Exception as e:
        print("project from chat failed: " + str(e)[:70])
        return None

    n = len(d.get('proposed') or [])
    if not n:
        return ("A don open **" + d['name'] + "** for yu projects, bo. "
                "A no fit pull clean tasks from di plan - open am and add dem yusef.")

    lines = [("\u2705 **" + d['name'] + "** don open, and a don draft "
              + str(n) + " task" + ("s" if n != 1 else "") + " from di plan:")]
    for t in (d['proposed'] or [])[:8]:
        lines.append("  \u00b7 " + t['title'])
    lines.append("")
    lines.append("Dem never touch yu board yet. Go Projects, tick di ones wey make sense, "
                 "and drop di rest. Na yu get di last word.")
    return chr(10).join(lines)


def _find_item(name, only_open=True):
    """Find what he means across tasks, todos and reminders. Best match or None."""
    name = (name or '').strip().strip('"\'').lower()
    if len(name) < 3:
        return None
    OPEN_T = "status NOT IN ('done','completed','cancelled')"
    found = []
    try:
        for row in (db.query("SELECT id, title, status FROM tasks WHERE "
                             + (OPEN_T if only_open else "1=1")) or []):
            found.append(('task', row['id'], row['title'] or ''))
        for row in (db.query("SELECT id, title, status FROM todos WHERE "
                             + ("status = 'pending'" if only_open else "1=1")) or []):
            found.append(('todo', row['id'], row['title'] or ''))
        for row in (db.query("SELECT id, title, status FROM reminders WHERE "
                             + ("status != 'completed'" if only_open else "1=1")) or []):
            found.append(('reminder', row['id'], row['title'] or ''))
        # the shopping list too - "take milk off the list"
        for row in (db.query("SELECT id, title FROM shopping_items WHERE "
                             + ("COALESCE(is_checked,0) = 0" if only_open else "1=1")) or []):
            found.append(('shopping', row['id'], row['title'] or ''))
    except Exception:
        return None

    # exact, then starts-with, then contains, then most words shared
    for kind, i, t in found:
        if t.lower().strip() == name:
            return (kind, i, t)
    for kind, i, t in found:
        if t.lower().startswith(name) or name.startswith(t.lower()):
            return (kind, i, t)
    for kind, i, t in found:
        if name in t.lower() or t.lower() in name:
            return (kind, i, t)
    # word overlap, but only on words that carry meaning, and only when most
    # of them match. a loose match here means deleting the wrong thing.
    STOP = {'the', 'and', 'for', 'about', 'with', 'that', 'this', 'from', 'task',
            'todo', 'reminder', 'please', 'can', 'you', 'my', 'all'}
    words = {w for w in name.split() if len(w) > 2 and w not in STOP}
    if len(words) >= 2:
        best, score = None, 0
        for kind, i, t in found:
            tw = {w for w in t.lower().split() if len(w) > 2 and w not in STOP}
            n = len(words & tw)
            # at least two real words, and most of what he said
            if n >= 2 and n >= len(words) * 0.6 and n > score:
                best, score = (kind, i, t), n
        if best:
            return best
    return None


def _act_on_existing(query):
    """Finish it, remove it, or reopen it. Returns a reply, or None to carry on."""
    import re as _r
    low = (query or '').strip().lower().rstrip('.!')
    if len(low) > 120:
        return None

    # what does he want done?
    if _r.search(r"\b(delete|remove|bin|get rid of|take .* off|scrap|cancel)\b", low):
        action = 'delete'
    elif _r.search(r"\b(done|complete[d]?|finished|ticked?|mark .* off|sorted|"
                   r"i did|i've done|i have done)\b", low):
        action = 'done'
    elif _r.search(r"\b(reopen|undo|not done|put .* back)\b", low):
        action = 'reopen'
    else:
        return None
    if '?' in low:
        return None

    # the one she just made?
    if _r.search(r"\b(that one|the one you just|you just (made|created|added)|"
                 r"the last one|that task|that todo)\b", low):
        last = db.query("""SELECT id, title FROM tasks
                           WHERE DATE(created_at) >= date('now','-1 day')
                           ORDER BY id DESC LIMIT 1""")
        if not last:
            return ("A no sabi which one yu mean, bo - tell mi di name and a go sort am.")
        kind, i, title = 'task', last[0]['id'], last[0]['title']
    else:
        # pull the name out of what he said
        m = _r.search(r"(?:delete|remove|bin|scrap|cancel|complete|finish|tick off|"
                      r"mark(?: the)?|mark off)\s+(?:the\s+|my\s+|that\s+)?"
                      r"(?:task|todo|to-?do|reminder)?\s*"
                      r"[\"\']?([a-z0-9][^\"\']{2,60}?)[\"\']?\s*"
                      r"(?:\s+(?:as\s+)?(?:done|complete[d]?|finished|off))?$", low)
        if not m:
            m = _r.search(r"^(?:i\s+)?(?:have\s+|i've\s+)?(?:done|finished)\s+"
                          r"(?:the\s+|my\s+)?(.{3,60})$", low)
        if not m:
            return None
        raw = m.group(1).strip()
        raw = _r.sub(r"^(the|my|that|a|an)\s+", "", raw)
        raw = _r.sub(r"\s+(task|todo|to-?do|reminder)$", "", raw)
        hit = _find_item(raw, only_open=(action != 'reopen'))
        if not hit:
            near = db.query("""SELECT title FROM tasks
                               WHERE status NOT IN ('done','completed','cancelled')
                               ORDER BY id DESC LIMIT 3""") or []
            msg = "A no fit find \"" + raw[:40] + "\" pan mi list, bo."
            if near:
                msg += " Di last tree wey dey: " + "; ".join(
                    str(r['title'])[:34] for r in near) + "."
            return msg
        kind, i, title = hit

    tbl = {'task': 'tasks', 'todo': 'todos', 'reminder': 'reminders',
           'shopping': 'shopping_items'}[kind]
    try:
        if action == 'delete':
            db.execute("DELETE FROM " + tbl + " WHERE id = ?", (i,))
            gone = not db.query("SELECT id FROM " + tbl + " WHERE id = ?", (i,))
            if not gone:
                return "A try for komot am but e no gree. Try from di screen, bo."
            return "\U0001F5D1 Komot: " + title + "."
        if action == 'reopen':
            db.execute("UPDATE " + tbl + " SET status = 'pending' WHERE id = ?", (i,))
            return "\u21a9 Put back pan di list: " + title + "."
        if kind == 'shopping':
            db.execute("UPDATE shopping_items SET is_checked = 1 WHERE id = ?", (i,))
            return "\u2705 Got am: " + title + "."
        done_val = 'completed' if kind == 'reminder' else 'done'
        db.execute("UPDATE " + tbl + " SET status = ? WHERE id = ?", (done_val, i))
        row = db.query("SELECT status FROM " + tbl + " WHERE id = ?", (i,))
        if not row or str(row[0]['status']) != done_val:
            return "A try for tick am but e no save. Try from di screen, bo."
        return "\u2705 Done: " + title + "."
    except Exception as e:
        print("act on existing failed: " + str(e)[:70])
        return None


def _in_usd(amount, currency):
    """A rough USD figure beside the local one. Not accounting - an idea."""
    try:
        cur = (currency or 'USD').upper()[:4]
        if cur == 'USD':
            return float(amount or 0)
        r = db.query("SELECT rate_to_usd FROM fx_rates WHERE currency = ?", (cur,))
        if not r:
            return None
        return round(float(amount or 0) * float(r[0]['rate_to_usd'] or 0), 2)
    except Exception:
        return None


def _money_line(amount, currency):
    """1,500 SLE (~61 USD) - or just the number when it is already dollars."""
    cur = (currency or 'USD').upper()[:4]
    base = "{:,.0f}".format(float(amount or 0)) + " " + cur
    if cur == 'USD':
        return base
    u = _in_usd(amount, cur)
    return base + ((" (~" + "{:,.0f}".format(u) + " USD)") if u else "")


def _find_contact(name):
    """One person, one record. "Nadine" is the same woman as
    "Nadine Nikuze Mushimiyimana"; Mr Allie on a job is Mr Allie in contacts."""
    nm = (name or '').strip()
    if len(nm) < 2:
        return None, nm
    try:
        r = db.query("""SELECT id, name FROM contacts
                        WHERE LOWER(name) = LOWER(?) OR LOWER(name) LIKE LOWER(?)
                           OR LOWER(COALESCE(aliases,'')) LIKE LOWER(?)
                        ORDER BY LENGTH(name) LIMIT 1""",
                     (nm, nm + ' %', '%' + nm + '%'))
        if r:
            return r[0]['id'], r[0]['name']
    except Exception:
        pass
    return None, nm


def _money_person(name):
    """Find whoever he means, across every job. Returns (person, project)."""
    nm = (name or '').strip().lower()
    if len(nm) < 2:
        return None, None
    rows = db.query("""SELECT p.id, p.name, p.trade, p.venture_id, v.name AS project
                       FROM job_people p
                       LEFT JOIN ventures v ON v.id = p.venture_id
                       WHERE COALESCE(p.active,1) = 1""") or []
    for r in rows:
        if str(r['name']).lower() == nm:
            return r, r.get('project')
    for r in rows:
        if nm in str(r['name']).lower() or str(r['name']).lower() in nm:
            return r, r.get('project')
    # by first name, which is how he talks
    first = nm.split()[0]
    for r in rows:
        if first and first in str(r['name']).lower().split():
            return r, r.get('project')
    return None, None


def _job_currency(venture_id):
    """Whatever this job is quoted in. SLe for Freetown, USD for a dev abroad."""
    r = db.query("""SELECT currency FROM job_quotes WHERE venture_id = ?
                    AND currency IS NOT NULL ORDER BY id DESC LIMIT 1""", (venture_id,))
    if r:
        return (r[0]['currency'] or 'USD').upper()[:4]
    r = db.query("""SELECT currency FROM stipend_terms WHERE venture_id = ?
                    ORDER BY id DESC LIMIT 1""", (venture_id,))
    return ((r[0]['currency'] if r else 'USD') or 'USD').upper()[:4]


def _money_sum(person_id, venture_id):
    """Quoted, paid, owed - worked out, never stored."""
    q = (db.query("""SELECT COALESCE(SUM(amount),0) AS s FROM job_quotes
                     WHERE person_id = ?""", (person_id,)) or [{"s": 0}])[0]['s'] or 0
    p = (db.query("""SELECT COALESCE(SUM(amount),0) AS s FROM job_payments
                     WHERE person_id = ?""", (person_id,)) or [{"s": 0}])[0]['s'] or 0
    return float(q), float(p), float(q) - float(p)


def _birthday_from_chat(query):
    """A birthday he mentions, or gives when she asks. Saved, then read back.

    "Nadine's birthday is the 26th" works on its own. So does "the 26th of
    this month" when the thing before it was her asking whose birthday.
    """
    import re as _rk
    low = (query or '').strip().lower()
    if len(low) < 4 or len(low) > 140:
        return None

    who, when = None, None

    # name and date in the one sentence
    m = _rk.search(r"([A-Z][a-z]+(?:\s+[A-Z][a-z]+)?)(?:'s)?\s+"
                   r"(?:birthday|bday|born)\b[^0-9A-Za-z]{0,12}(.+)$", query)
    if m:
        who = m.group(1).strip()
        when = _extract_birthday_date(m.group(2))

    # or he is answering her question from the turn before
    if not who and _rk.search(r"\b(\d{1,2})(?:st|nd|rd|th)?\b", low):
        when = _extract_birthday_date(query)
        if when:
            last = db.query("""SELECT user_message, ami_response FROM conversations
                               ORDER BY id DESC LIMIT 2""") or []
            for row in last:
                text = str(row.get('ami_response') or '') + " " + str(row.get('user_message') or '')
                if 'birthday' not in text.lower() and 'bday' not in text.lower():
                    continue
                nm = _rk.search(r"\b([A-Z][a-z]{2,})\b(?:'s)?\s*(?:in|)\s*"
                                r"(?:birthday|bday)", text)
                if not nm:
                    nm = _rk.search(r"(?:birthday|bday)[^A-Za-z]{0,10}"
                                    r"(?:for|of)?\s*\b([A-Z][a-z]{2,})\b", text)
                if nm and nm.group(1).lower() not in ('yu', 'his', 'her', 'the', 'and'):
                    who = nm.group(1)
                    break

    if not who or not when:
        return None

    try:
        # he says "Nadine"; the contact is "Nadine Nikuze Mushimiyimana"
        _c = db.query("""SELECT id, name FROM contacts
                         WHERE LOWER(name) = LOWER(?) OR LOWER(name) LIKE LOWER(?)
                         ORDER BY LENGTH(name) LIMIT 1""", (who, who + ' %'))
        _cid = _c[0]['id'] if _c else None
        if _c:
            who = _c[0]['name']          # keep his real name on the list
        found = db.query("SELECT id, date FROM user_birthdays WHERE LOWER(name) = LOWER(?) "
                         "OR (contact_id IS NOT NULL AND contact_id = ?)",
                         (who, _cid))
        if found:
            if str(found[0]['date']) == when:
                return None          # she already knows, nothing to say
            db.execute("UPDATE user_birthdays SET date = ? WHERE id = ?", (when, found[0]['id']))
        else:
            db.execute("INSERT INTO user_birthdays (name, date, contact_id) "
                       "VALUES (?, ?, ?)", (who, when, _cid))
        back = db.query("SELECT date FROM user_birthdays WHERE LOWER(name) = LOWER(?)", (who,))
        if not back or str(back[0]['date']) != when:
            return "A try for save am but e no stick. Add am from di birthday screen, bo."
        from datetime import datetime as _dk
        nice = _dk.strptime("2000-" + when, "%Y-%m-%d").strftime("%-d %B")
        return "\U0001F382 " + who + " - " + nice + ". A don put am pan di list."
    except Exception as e:
        print("birthday from chat failed: " + str(e)[:70])
        return None


def _push_meds_later(query):
    """He is flying, or out, and cannot take them now. Nudge him later
    instead of going quiet about it."""
    import re as _rp
    from datetime import timedelta as _tp
    low = (query or '').strip().lower()
    if not _rp.search(r"\b(med|meds|medication|pill|tablet)", low):
        return None
    m = _rp.search(r"\b(?:remind|nudge|tell|ask)\s+mi?e?\b.{0,24}?"
                   r"\b(?:in|after)\s+(\d{1,2})\s*(hour|hr|minute|min)", low)
    if not m:
        m = _rp.search(r"\b(?:push|move|delay)\b.{0,24}?\b(\d{1,2})\s*(hour|hr|minute|min)", low)
    if not m:
        return None
    n = int(m.group(1))
    mins = n * 60 if m.group(2).startswith(('hour', 'hr')) else n
    when = (_charlie_now() + _tp(minutes=mins)).strftime('%Y-%m-%d %H:%M:%S')
    try:
        db.execute("INSERT OR REPLACE INTO user_settings (key, value) VALUES "
                   "('meds_quiet_until', ?)", (when,))
        back = db.query("SELECT value FROM user_settings WHERE key = 'meds_quiet_until'")
        if not back:
            return None
        nice = (str(n) + " hours" if mins >= 60 else str(n) + " minutes")
        return "\u23F0 Fine. A go remind yu about yu meds in " + nice + "."
    except Exception as e:
        print("meds later failed: " + str(e)[:60])
        return None


def _ledger_person_by_name(name):
    """Whoever he means. Falls back to his contacts so "Ingie" finds her."""
    nm = (name or '').strip().lower()
    if len(nm) < 2:
        return None
    rows = db.query("""SELECT id, name FROM ledger_people
                       WHERE COALESCE(active,1) = 1""") or []
    for r in rows:
        if str(r['name']).lower() == nm:
            return r
    for r in rows:
        if nm in str(r['name']).lower() or str(r['name']).lower().startswith(nm):
            return r
    first = nm.split()[0]
    for r in rows:
        if first in str(r['name']).lower().split():
            return r
    # "paint guy" is the painter; "door man" is the door guy
    stop = {'guy', 'man', 'woman', 'person', 'the', 'mr', 'mrs', 'my'}
    words = [w for w in nm.replace('-', ' ').split() if w not in stop and len(w) > 2]
    for w in words:
        stem = w[:5]
        for r in rows:
            if stem and stem in str(r['name']).lower():
                return r
    return None


def _ledger_breakdown(person, name):
    """Every line with this person, in order, with what is left at the end."""
    rows = db.query("""SELECT e.kind, e.amount, e.currency, e.note, e.happened_on,
                              e.how_sent, e.status, v.name AS job
                       FROM ledger_entries e
                       LEFT JOIN ventures v ON v.id = e.venture_id
                       WHERE e.person_id = ?
                       ORDER BY e.happened_on, e.id""", (person,)) or []
    if not rows:
        return "Nothing pan mi book for " + name + " yet, bo."

    agreed = paid = 0.0
    cur = ''
    out_in, out_back = [], []
    for r in rows:
        if str(r.get('status')) in ('forgiven', 'done'):
            continue
        cur = cur or (r.get('currency') or '')
        amt = float(r.get('amount') or 0)
        when = str(r.get('happened_on') or '')[:10]
        what = str(r.get('note') or '')[:44]
        job = (" [" + str(r['job']) + "]") if r.get('job') else ""
        k = str(r['kind'])
        if k in ('agreed', 'lent', 'borrowed', 'bought'):
            agreed += amt
            out_in.append("  " + when + "  " + "{:,.0f}".format(amt) + "  " + what + job)
        elif k in ('paid', 'repaid'):
            paid += amt
            how = (" (" + str(r['how_sent']) + ")") if r.get('how_sent') else ""
            out_back.append("  " + when + "  " + "{:,.0f}".format(amt) + "  "
                            + what + how + job)

    L = [name]
    if out_in:
        L.append("")
        L.append("Wetin una gree:")
        L.extend(out_in[:14])
        if len(out_in) > 14:
            L.append("  ... and " + str(len(out_in) - 14) + " more")
        L.append("  " + "all of it".ljust(12) + "{:,.0f}".format(agreed) + " " + cur)
    if out_back:
        L.append("")
        L.append("Wetin yu don pay:")
        L.extend(out_back[:14])
        if len(out_back) > 14:
            L.append("  ... and " + str(len(out_back) - 14) + " more")
        L.append("  " + "all of it".ljust(12) + "{:,.0f}".format(paid) + " " + cur)
    L.append("")
    left = round(agreed - paid, 2)
    if abs(left) < 0.01:
        L.append("Una dey level - nothing lef.")
    elif left > 0:
        L.append("Still owing: " + _money_s(left, cur))
    else:
        L.append("Yu don overpay by " + _money_s(-left, cur) + ".")
    return "\n".join(L)


def _ledger_say(pid, name):
    """Where it stands. A builder with an unpaid agreement is owed money by
    him - not the other way round, however the arithmetic signs it."""
    bal = _ledger_balance(pid)
    # did he agree work with them, or lend them money?
    kinds = db.query("""SELECT DISTINCT kind FROM ledger_entries
                        WHERE person_id = ?""", (pid,)) or []
    ks = {str(k['kind']) for k in kinds}
    for_work = ('agreed' in ks) and not (ks & {'lent'})
    parts = []
    for cur, b in bal.items():
        if abs(b['net']) < 0.01:
            continue
        if b['net'] > 0:
            if for_work:
                parts.append("yu still owe " + name + " " + _money_s(b['net'], cur)
                             + " for di work")
            else:
                parts.append(name + " still owe yu " + _money_s(b['net'], cur))
        else:
            parts.append("yu still owe " + name + " " + _money_s(-b['net'], cur))
    return "; ".join(parts) if parts else ("Yu and " + name + " dey level.")


def _ledger_from_chat_inner(query):
    """Money between him and someone. Returns a reply, or None."""
    # Krio teaching - reads only, so it can go first
    try:
        _kr = _krio_from_chat(query)
        if _kr:
            return _kr
    except Exception as _kre:
        import traceback as _tbk
        print('KRIO HOOK FAILED:', repr(_kre), flush=True)
        _tbk.print_exc()
    # medicine before money - 'I took' must never be just words
    try:
        _md = _med_from_chat(query)
        if _md:
            return _md
    except Exception as _mde:
        import traceback as _tbm
        print('MEDS HOOK FAILED:', repr(_mde), flush=True)
        _tbm.print_exc()
    # proverbs and Krio - never touches anything, safe first
    try:
        _pv = _proverb_from_chat(query)
        if _pv:
            return _pv
    except Exception as _pve:
        import traceback as _tbp
        print('PROVERBS HOOK FAILED:', repr(_pve), flush=True)
        _tbp.print_exc()
    # what he drives - this never touches money, so it is safe first
    try:
        _vh = _vehicle_chat(query)
        if _vh:
            return _vh
    except Exception as _vhe:
        import traceback as _tbv
        print('VEHICLES HOOK FAILED:', repr(_vhe), flush=True)
        _tbv.print_exc()
    # the buy list first - it never moves money, so it is safe here
    try:
        _bl = _buy_from_chat(query)
        if _bl:
            return _bl
    except Exception as _ble:
        import traceback as _tbh
        print('BUY LIST HOOK FAILED:', repr(_ble), flush=True)
        _tbh.print_exc()
    import re as _rl
    from datetime import datetime as _dl
    q = (query or '').strip()
    low = q.lower()
    if len(low) < 6 or len(low) > 220:
        return None

    # he is ASKING, not telling. a question never moves money - "how much have
    # I paid Mr Allie since Phase 1" is not a payment of one leone.
    _asking = bool(_rl.match(r"^(and\s+)?(how|what|what's|whats|when|who|where|why|"
                             r"show|list|tell|give me|break|can yu|can you|"
                             r"do i|did i|am i|is there|any)\b", low)
                   or low.rstrip().endswith('?'))

    # the itemised answer, when he wants to see it line by line
    if _asking:
        _bm = _rl.search(r"(?:everything|all|breakdown|break down|itemi[sz]e|history|"
                         r"every line|line by line|how much have i paid|"
                         r"how much did i pay|what have i paid|since phase)"
                         r"[^a-z]{0,12}(?:i\s+)?(?:paid|pay|owe|owed|gave|sent|to|for|"
                         r"with|on)?\s*([a-z][a-z .'-]{1,30}?)\s*\??$", low)
        if not _bm:
            _bm = _rl.search(r"(?:how much have i paid|how much did i pay|"
                             r"what did i pay|what have i spent on|"
                             r"what have i paid|everything (?:i )?paid|"
                             r"break down|breakdown (?:of|for)?)\s+"
                             r"(?:the\s+)?([a-z][a-z .'-]{1,30}?)"
                             r"(?:\s+(?:since|in|for|on|during|over|last|this)\b.*)?"
                             r"\s*\??$", low)
        # a thing, not a person - "what did cement cost me last time"
        _tm = _rl.search(r"(?:what (?:did|does|do)|how much (?:did|does|is|was|have))"
                         r"[^a-z]{0,6}(?:i |it |we )?"
                         r"(?:cost|pay|paid|spend|spent)?[^a-z]{0,4}"
                         r"(?:for |on )([a-z][a-z ]{2,24}?)"
                         r"(?:\s+(?:cost|last time|before|usually|normally))?\s*\??$", low)
        if not _tm:
            _tm = _rl.search(r"(?:price of|cost of|what does|how much is)\s+"
                             r"(?:a |the )?([a-z][a-z ]{2,24}?)"
                             r"(?:\s+(?:cost|usually|normally|go for))?\s*\??$", low)
        if _tm:
            _thing = _rl.sub(r"\b(the|a|an|me|us|usually|normally|last time)\b", "",
                             _tm.group(1)).strip()
            if _thing and not _ledger_person_by_name(_thing):
                _ta = _thing_answer(_thing)
                if _ta:
                    return _ta

        if _bm:
            _who = _rl.sub(r"\b(since|from|for|in|on|phase|the)\b.*$", "",
                           _bm.group(1)).strip()
            _p = _ledger_person_by_name(_who or _bm.group(1))
            if _p:
                return _ledger_breakdown(_p['id'], _p['name'])
    if not _rl.search(r"\b(owe|owes|owed|paid|pay|sent|send|lent|lend|loan|borrow|"
                      r"borrowed|repay|repaid|gave|give|gift|bought|buy|balance|"
                      r"write off|forget what)\b", low):
        # "how about the door guy" carries the money question forward
        if not _rl.search(r"^(?:and\s+)?(?:how|what)\s+about\s+", low):
            return None

    MONEY = (r"(?:usd|\$|sle|le|cad|ksh|gh[sc])?\s*([\d][\d,]*(?:\.\d+)?)\s*"
             r"(usd|dollars?|sle|leones?|cad|ksh|ghs)?")

    def _cur(word, person_id=None):
        w = (word or '').lower()
        if w.startswith('cad'):
            return 'CAD'
        if w.startswith(('sle', 'leone')):
            return 'SLE'
        if w.startswith('ksh'):
            return 'KES'
        if w.startswith('gh'):
            return 'GHS'
        if w.startswith(('usd', 'dollar')) or w == '$':
            return 'USD'
        if person_id:
            r = db.query("""SELECT currency FROM ledger_entries WHERE person_id = ?
                            ORDER BY id DESC LIMIT 1""", (person_id,))
            if r:
                return (r[0]['currency'] or 'USD').upper()[:4]
        return 'USD'

    def _add(person, kind, amount, cur, note, side=None):
        db.execute("""INSERT INTO ledger_entries (person_id, kind, who_owes, amount,
                      currency, note, happened_on)
                      VALUES (?,?,?,?,?,?,?)""",
                   (person['id'], kind,
                    side or ('me' if kind in ('borrowed', 'bought') else 'them'),
                    amount, cur, note[:160], _dl.now().strftime('%Y-%m-%d')))
        return bool(db.query("""SELECT id FROM ledger_entries WHERE person_id = ?
                                AND amount = ? ORDER BY id DESC LIMIT 1""",
                             (person['id'], amount)))

    # --- he sent money to someone ----------------------------------------
    m = None if _asking else _rl.search(r"\b(?:i\s+)?(?:just\s+)?(?:sent|paid|gave)\s+"
                   r"([a-z][a-z .'-]{1,28}?)\s+" + MONEY, low)
    if m and 'gift' not in low:
        person = _ledger_person_by_name(m.group(1))
        if not person:
            return ("A no get " + m.group(1).strip().title() + " pan mi book yet, bo. "
                    "Add am first and a go track am.")
        amt = float(m.group(2).replace(',', ''))
        cur = _cur(m.group(3), person['id'])
        bal = _ledger_balance(person['id'])
        owes_him = any(b['net'] > 0 for b in bal.values())
        kind = 'paid' if owes_him else 'repaid'
        if not _add(person, kind, amt, cur, q, side=('them' if owes_him else 'me')):
            return "A try for write am down but e no save, bo."
        return ("\U0001F4B0 " + _money_s(amt, cur) + " to " + person['name']
                + ". " + _ledger_say(person['id'], person['name']))

    # --- someone paid him -------------------------------------------------
    m = None if _asking else _rl.search(r"\b([a-z][a-z .'-]{1,28}?)\s+(?:paid|sent|gave)\s+mi?e?\s+" + MONEY, low)
    if m:
        person = _ledger_person_by_name(m.group(1))
        if person:
            amt = float(m.group(2).replace(',', ''))
            cur = _cur(m.group(3), person['id'])
            if not _add(person, 'repaid', amt, cur, q, side='them'):
                return "A try for write am down but e no save, bo."
            return ("\U0001F4B0 " + person['name'] + " pay " + _money_s(amt, cur)
                    + ". " + _ledger_say(person['id'], person['name']))

    # --- he lent, or took, money -----------------------------------------
    m = None if _asking else _rl.search(r"\bi\s+(?:just\s+)?(lent|loaned|borrowed)\s+"
                   r"(?:from\s+)?([a-z][a-z .'-]{1,28}?)\s+" + MONEY, low)
    if not m:
        m2 = _rl.search(r"\b([a-z][a-z .'-]{1,28}?)\s+(?:lent|loaned)\s+mi?e?\s+" + MONEY, low)
        if m2:
            person = _ledger_person_by_name(m2.group(1))
            if person:
                amt = float(m2.group(2).replace(',', ''))
                cur = _cur(m2.group(3), person['id'])
                if not _add(person, 'borrowed', amt, cur, q):
                    return "A try for write am down but e no save, bo."
                return ("\U0001F4DD Yu borrow " + _money_s(amt, cur) + " from "
                        + person['name'] + ". " + _ledger_say(person['id'], person['name']))
    if m:
        word, who, amount, curw = m.group(1), m.group(2), m.group(3), m.group(4)
        person = _ledger_person_by_name(who)
        if not person:
            return ("A no get " + who.strip().title() + " pan mi book. Add am first, bo.")
        amt = float(amount.replace(',', ''))
        cur = _cur(curw, person['id'])
        kind = 'borrowed' if word == 'borrowed' else 'lent'
        if not _add(person, kind, amt, cur, q):
            return "A try for write am down but e no save, bo."
        verb = ("Yu borrow " if kind == 'borrowed' else "Yu lend ")
        return ("\U0001F4DD " + verb + _money_s(amt, cur)
                + (" from " if kind == 'borrowed' else " to ") + person['name']
                + ". " + _ledger_say(person['id'], person['name']))

    # --- someone bought something for him ---------------------------------
    m = None if _asking else _rl.search(r"\b([a-z][a-z .'-]{1,28}?)\s+(?:bought|buy|got)\s+(?:mi?e?\s+)?"
                   r"(.{2,34}?)\s+(?:for\s+)?" + MONEY, low)
    if m:
        person = _ledger_person_by_name(m.group(1))
        if person:
            amt = float(m.group(3).replace(',', ''))
            cur = _cur(m.group(4), person['id'])
            if not _add(person, 'bought', amt, cur, m.group(2).strip()):
                return "A try for write am down but e no save, bo."
            return ("\U0001F4DD " + person['name'] + " buy " + m.group(2).strip()
                    + " - " + _money_s(amt, cur) + ". "
                    + _ledger_say(person['id'], person['name']))

    # --- a gift -----------------------------------------------------------
    m = _rl.search(r"\b(?:i\s+)?(?:gave|give)\s+([a-z][a-z .'-]{1,28}?)\s+"
                   + MONEY + r".{0,20}\bgift\b", low)
    if not m:
        m = _rl.search(r"\bgift\b.{0,20}?([a-z][a-z .'-]{1,28}?)\s+" + MONEY, low)
    if m:
        person = _ledger_person_by_name(m.group(1))
        if person:
            amt = float(m.group(2).replace(',', ''))
            cur = _cur(m.group(3), person['id'])
            if not _add(person, 'gift', amt, cur, q, side='them'):
                return "A try for write am down but e no save, bo."
            return ("\U0001F381 Gift to " + person['name'] + ": " + _money_s(amt, cur)
                    + ". E no dey pan di balance.")

    # --- what does X owe me, or what do I owe X ---------------------------
    m = _rl.search(r"\b(?:how much (?:do(?:es)? )?)?(?:what )?(?:do(?:es)? )?"
                   r"(?:i\s+owe\s+)?([a-z][a-z .'-]{1,28}?)\s*"
                   r"(?:owes?\s+mi?e?)?\s*\??$", low)
    if _rl.search(r"\bowe", low) and m:
        who = m.group(1).strip()
        who = _rl.sub(r"^(what|how much|do|does|i|me|mi)\s+", "", who).strip()
        person = _ledger_person_by_name(who)
        if person:
            line = _ledger_say(person['id'], person['name'])
            loan = db.query("""SELECT amount, currency, repay_amount FROM ledger_entries
                               WHERE person_id = ? AND kind IN ('lent','borrowed')
                               ORDER BY id DESC LIMIT 1""", (person['id'],))
            if loan and loan[0].get('repay_amount'):
                bal = _ledger_balance(person['id'])
                for cur, b in bal.items():
                    per = float(loan[0]['repay_amount'] or 0)
                    if per > 0 and abs(b['net']) > 0:
                        n = int(abs(b['net']) / per) + (1 if abs(b['net']) % per else 0)
                        line += " At " + "{:,.0f}".format(per) + " a month na " + str(n) + " months."
                        break
            return line

    # "how about the door guy" - same question, different person. and he may
    # carry on in the same breath: "how about the paint guy? what do I owe him"
    m = _rl.search(r"^(?:and\s+)?(?:how|what)\s+about\s+(?:the\s+)?"
                   r"([a-z][a-z .'-]{2,30}?)\s*(?:[?.,!]|$)", low)
    if m:
        _rest = low[m.end():]
        person = _ledger_person_by_name(m.group(1))
        if person:
            if _rl.search(r"\b(everything|every line|break\s?down|itemi[sz]e|"
                          r"history|how much have i paid|what did i pay)\b", _rest):
                return _ledger_breakdown(person['id'], person['name'])
            return _ledger_say(person['id'], person['name'])
        return ("A no get " + m.group(1).strip().title()
                + " pan mi book, bo. Add am and a go track am.")

    # --- who owes me, altogether ------------------------------------------
    if _rl.search(r"\bwho\s+(?:owes?|dey owe)\s+mi?e?\b", low):
        d = ledger_overview()
        if isinstance(d, tuple):
            d = d[0]
        them = d.get('they_owe_him') or []
        if not them:
            return "Nobody owe yu anything right now, bo."
        return ("Dem wey owe yu: "
                + "; ".join(x['name'] + " " + _money_s(x['amount'], x['currency'])
                            for x in them[:8]) + ".")

    if _rl.search(r"\bwho\s+(?:do\s+)?i\s+owe\b|\bwhat\s+do\s+i\s+owe\b", low):
        d = ledger_overview()
        if isinstance(d, tuple):
            d = d[0]
        mine = d.get('he_owes') or []
        if not mine:
            return "Yu no owe anybody, bo."
        return ("Yu owe: " + "; ".join(x['name'] + " " + _money_s(x['amount'], x['currency'])
                                       for x in mine[:8]) + ".")

    return None


def _money_breakdown(query):
    """Everything paid to one person, or everything on one job. He asks for
    the detail when he is checking against Aminata's book."""
    import re as _rb
    low = (query or '').strip().lower()
    if not _rb.search(r"\b(show|list|break\s*down|breakdown|everything|all)\b", low):
        return None
    if not _rb.search(r"\b(paid|payment|spent|cost)\b", low):
        return None

    # everything paid to one person
    m = _rb.search(r"(?:paid|payments? to|spent on)\s+([a-z][a-z .'-]{1,28}?)\s*\??$", low)
    if m:
        person, project = _money_person(m.group(1).strip())
        if person:
            rows = db.query("""SELECT amount, what, paid_on FROM job_payments
                               WHERE person_id = ? ORDER BY paid_on, id""",
                            (person['id'],)) or []
            if not rows:
                return "Yu never pay " + person['name'] + " anything yet, bo."
            cur = _job_currency(person['venture_id'])
            lines = [person['name'] + " - everything yu don pay am:"]
            total = 0.0
            for r in rows:
                a = float(r['amount'] or 0)
                total += a
                lines.append("  " + str(r['paid_on'] or '') + "  "
                             + "{:,.0f}".format(a)
                             + (("  " + str(r['what'])[:40]) if r.get('what') else ""))
            quoted, paid, owed = _money_sum(person['id'], person['venture_id'])
            lines.append("  Total " + _money_line(total, cur)
                         + ", still owing " + _money_line(owed, cur) + ".")
            return "\n".join(lines)

    # everything on one job
    m = _rb.search(r"\b(?:for|on|pan)\s+(?:di\s+|the\s+)?([a-z][a-z ]{2,30}?)\s*\??$", low)
    if m:
        v = db.query("""SELECT id, name FROM ventures WHERE LOWER(name) LIKE ?
                        AND COALESCE(active,1) = 1 ORDER BY LENGTH(name) LIMIT 1""",
                     ('%' + m.group(1).strip() + '%',))
        if v:
            pid = v[0]['id']
            ids = _all_under(pid)
            inlist = ",".join(str(i) for i in ids)
            rows = db.query("""SELECT y.amount, y.what, y.paid_on, p.name
                               FROM job_payments y
                               LEFT JOIN job_people p ON p.id = y.person_id
                               WHERE y.venture_id IN (""" + inlist + """)
                               ORDER BY y.paid_on, y.id""") or []
            if not rows:
                return "Nothing don go out pan " + str(v[0]['name']) + " yet, bo."
            cur = _job_currency(pid)
            lines = [str(v[0]['name']) + " - everything wey don go out:"]
            total = 0.0
            for r in rows:
                a = float(r['amount'] or 0)
                total += a
                lines.append("  " + str(r['paid_on'] or '') + "  "
                             + "{:,.0f}".format(a) + "  "
                             + str(r.get('name') or r.get('what') or '')[:38])
            lines.append("  Total " + _money_line(total, cur) + ".")
            return "\n".join(lines)
    return None


def _money_from_chat(query):
    """Money talk about a job. Returns a reply, or None to carry on."""
    import re as _rm
    from datetime import datetime as _dm
    q = (query or '').strip()
    low = q.lower()
    if len(low) < 6 or len(low) > 200:
        return None
    if not _rm.search(r"\b(owe|owed|paid|pay|paying|cost|quote[ds]?|spent|budget|"
                      r"charge[ds]?|balance)\b", low):
        return None

    # he wants the whole list, not just the total
    _bd = _money_breakdown(q)
    if _bd:
        return _bd

    money = r"(?:usd|\$|sle|le|ksh|gh[sc])?\s*([\d][\d,]*(?:\.\d+)?)\s*(?:usd|dollars?|sle|le|k)?"

    # --- he paid someone -------------------------------------------------
    m = _rm.search(r"\b(?:i\s+)?(?:just\s+)?(?:paid|sent|gave)\s+"
                   r"([a-z][a-z .'-]{1,28}?)\s+" + money, low)
    if m:
        who, amount = m.group(1).strip(), m.group(2).replace(',', '')
        person, project = _money_person(who)
        if not person:
            return ("A no get " + who.title() + " pan any job yet, bo. Add am first "
                    "and a go track wetin yu pay am.")
        try:
            amt = float(amount)
        except Exception:
            return None
        if amt <= 0:
            return None
        db.execute("""INSERT INTO job_payments (venture_id, person_id, amount, kind,
                                                what, paid_on)
                      VALUES (?, ?, ?, 'labour', ?, ?)""",
                   (person['venture_id'], person['id'], amt, q[:80],
                    _dm.now().strftime('%Y-%m-%d')))
        if not db.query("""SELECT id FROM job_payments WHERE person_id = ? AND amount = ?
                           ORDER BY id DESC LIMIT 1""", (person['id'], amt)):
            return "A try for write am down but e no save. Try from di screen, bo."
        quoted, paid, owed = _money_sum(person['id'], person['venture_id'])
        cur = _job_currency(person['venture_id'])
        return ("\U0001F4B0 Noted: " + _money_line(amt, cur) + " to " + person['name']
                + ". Dat make " + _money_line(paid, cur) + " paid, "
                + _money_line(owed, cur) + " still owing pan " + str(project or 'di job')
                + ".")

    # --- a quote moved ---------------------------------------------------
    m = _rm.search(r"([a-z][a-z .'-]{1,28}?)\s+(?:say|says|said|wan|wants?|now)\s+"
                   r"(?:di\s+|the\s+)?([a-z ]{3,30}?)\s+(?:go\s+)?(?:is|will be|cost|"
                   r"costs?|na)\s+" + money, low)
    if m:
        who, what, amount = m.group(1).strip(), m.group(2).strip(), m.group(3).replace(',', '')
        person, project = _money_person(who)
        if person:
            rows = db.query("""SELECT id, what, amount FROM job_quotes
                               WHERE person_id = ?""", (person['id'],)) or []
            hit = None
            for r in rows:
                if what in str(r['what']).lower() or str(r['what']).lower() in what:
                    hit = r
                    break
            if hit:
                try:
                    new = float(amount)
                except Exception:
                    return None
                was = float(hit['amount'] or 0)
                if abs(new - was) > 0.004:
                    db.execute("""INSERT INTO job_quote_history (quote_id, was, now_is, why)
                                  VALUES (?, ?, ?, ?)""", (hit['id'], was, new, q[:120]))
                    db.execute("UPDATE job_quotes SET amount = ? WHERE id = ?",
                               (new, hit['id']))
                    pct = ((new - was) / was * 100) if was else 0
                    return ("\U0001F4C8 " + str(hit['what']) + ": was "
                            + "{:,.0f}".format(was) + ", now " + "{:,.0f}".format(new)
                            + " (" + "{:+.0f}".format(pct) + "%). A don keep di first "
                            "number so yu go know next time.")

    # --- what does he owe someone ----------------------------------------
    m = _rm.search(r"\b(?:how much (?:do )?i owe|what (?:do )?i owe|owe)\s+"
                   r"([a-z][a-z .'-]{1,28}?)\s*\??$", low)
    if m:
        person, project = _money_person(m.group(1).strip())
        if not person:
            return None
        quoted, paid, owed = _money_sum(person['id'], person['venture_id'])
        if not quoted and not paid:
            return ("Nothing down for " + person['name'] + " yet, bo.")
        cur = _job_currency(person['venture_id'])
        line = (person['name'] + ": quoted " + _money_line(quoted, cur)
                + ", paid " + _money_line(paid, cur) + ", owing "
                + _money_line(owed, cur) + ".")
        moved = db.query("""SELECT q.what, h.was, q.amount FROM job_quote_history h
                            JOIN job_quotes q ON q.id = h.quote_id
                            WHERE q.person_id = ? ORDER BY h.id DESC LIMIT 1""",
                         (person['id'],))
        if moved:
            m0 = moved[0]
            line += (" Mind yu, " + str(m0['what']) + " start at "
                     + "{:,.0f}".format(float(m0['was'] or 0)) + ".")
        return line

    # --- who do I owe on this job, and how much ---------------------------
    m = _rm.search(r"\bwho\s+(?:do\s+)?i\s+owe\b(?:.*?\b(?:on|for|in)\s+"
                   r"(?:di\s+|the\s+)?([a-z][a-z ]{2,28}?))?\s*\??$", low)
    if m:
        where = (m.group(1) or '').strip()
        if where:
            v = db.query("""SELECT id, name FROM ventures WHERE LOWER(name) LIKE ?
                            AND COALESCE(active,1) = 1 ORDER BY LENGTH(name) LIMIT 1""",
                         ('%' + where + '%',))
            ids = _all_under(v[0]['id']) if v else []
            label = v[0]['name'] if v else where
        else:
            ids, label = [], "everything"
        where_sql = ("AND p.venture_id IN (" + ",".join(str(i) for i in ids) + ")") if ids else ""
        rows = db.query("""SELECT p.name, v.name AS project,
                                  (SELECT COALESCE(SUM(amount),0) FROM job_quotes q
                                   WHERE q.person_id = p.id) AS quoted,
                                  (SELECT COALESCE(SUM(amount),0) FROM job_payments y
                                   WHERE y.person_id = p.id) AS paid
                           FROM job_people p
                           LEFT JOIN ventures v ON v.id = p.venture_id
                           WHERE COALESCE(p.active,1) = 1 """ + where_sql) or []
        owing = [(r['name'], float(r['quoted'] or 0) - float(r['paid'] or 0),
                  r.get('project') or '')
                 for r in rows if float(r['quoted'] or 0) > float(r['paid'] or 0)]
        if not owing:
            return "Yu no owe anybody right now, bo."
        owing.sort(key=lambda x: -x[1])
        bits = [a + " " + "{:,.0f}".format(b) + ((" (" + c + ")") if not where and c else "")
                for a, b, c in owing[:8]]
        total = sum(b for _, b, _ in owing)
        return ("Owing pan " + str(label) + ": " + "; ".join(bits)
                + ". Total " + "{:,.0f}".format(total) + ".")

    # --- what is outstanding across everything ----------------------------
    if _rm.search(r"\b(outstanding|all my (?:project|balance)|balances?)\b", low):
        rows = db.query("""SELECT v.name,
                                  (SELECT COALESCE(SUM(amount),0) FROM job_quotes q
                                   WHERE q.venture_id = v.id) AS quoted,
                                  (SELECT COALESCE(SUM(amount),0) FROM job_payments y
                                   WHERE y.venture_id = v.id) AS paid
                           FROM ventures v WHERE COALESCE(v.active,1) = 1""") or []
        out = [(r['name'], float(r['quoted'] or 0) - float(r['paid'] or 0))
               for r in rows if float(r['quoted'] or 0) > float(r['paid'] or 0)]
        if not out:
            return "Nothing outstanding pan any job, bo."
        out.sort(key=lambda x: -x[1])
        return ("Still owing: " + "; ".join(a + " " + "{:,.0f}".format(b) for a, b in out)
                + ". Altogether " + "{:,.0f}".format(sum(b for _, b in out)) + ".")

    # --- when did I last pay him ------------------------------------------
    m = _rm.search(r"\b(?:how much|when)\s+(?:did\s+)?i\s+(?:last\s+)?(?:pay|paid|send|sent)\s+"
                   r"([a-z][a-z .'-]{1,28}?)(?:\s+last(?:\s+time)?)?\s*\??$", low)
    if m:
        person, project = _money_person(m.group(1).strip())
        if not person:
            return None
        last = db.query("""SELECT amount, paid_on FROM job_payments
                           WHERE person_id = ? ORDER BY id DESC LIMIT 3""",
                        (person['id'],)) or []
        if not last:
            return "Yu never pay " + person['name'] + " yet, bo."
        bits = ["{:,.0f}".format(float(r['amount'] or 0)) + " pan " + str(r['paid_on'])
                for r in last]
        quoted, paid, owed = _money_sum(person['id'], person['venture_id'])
        return ("Last payment to " + person['name'] + ": " + bits[0]
                + (" (before dat: " + "; ".join(bits[1:]) + ")" if len(bits) > 1 else "")
                + ". Still owing " + "{:,.0f}".format(owed) + ".")

    # --- what has the whole job cost -------------------------------------
    m = _rm.search(r"\b(?:how much|what)\s+(?:has|have|did|do)?\s*"
                   r"(?:di\s+|the\s+)?([a-z][a-z ]{2,30}?)\s+"
                   r"(?:cost|spent|taken|eat)\b", low)
    if m:
        name = m.group(1).strip()
        v = db.query("""SELECT id, name FROM ventures
                        WHERE LOWER(name) LIKE ? AND COALESCE(active,1) = 1
                        ORDER BY LENGTH(name) LIMIT 1""", ('%' + name + '%',))
        if v:
            pid = v[0]['id']
            ids = _all_under(pid)
            inlist = ",".join(str(i) for i in ids)
            quoted = (db.query("SELECT COALESCE(SUM(amount),0) AS s FROM job_quotes "
                               "WHERE venture_id IN (" + inlist + ")")
                      or [{"s": 0}])[0]['s'] or 0
            paid = (db.query("SELECT COALESCE(SUM(amount),0) AS s FROM job_payments "
                             "WHERE venture_id IN (" + inlist + ")")
                    or [{"s": 0}])[0]['s'] or 0
            stip = (db.query("SELECT COALESCE(SUM(r.amount),0) AS s FROM stipend_runs r "
                             "JOIN stipend_terms t ON t.id = r.term_id "
                             "WHERE t.venture_id IN (" + inlist + ")")
                    or [{"s": 0}])[0]['s'] or 0
            out = float(paid) + float(stip)
            if not quoted and not out:
                return None
            return (str(v[0]['name']) + ": " + "{:,.0f}".format(out) + " don go out, "
                    + "{:,.0f}".format(float(quoted) - float(paid)) + " still owing.")

    return None


def _instant_time(text):
    """The clock does not need a language model."""
    import re as _r
    low = (text or '').strip().lower()
    low = low.strip(' ?.!')
    # only when the WHOLE message is asking the clock - not "what time are the
    # seahawks playing", not "what time is my meeting"
    if not _r.fullmatch(r"(hey |ok |so |and )?"
                        r"(what('?s| is)? (the )?time( is it)?( now| here| there)?"
                        r"|what time is it( now| here)?"
                        r"|time( now| check)?"
                        r"|wetin time (dey|be) (it|now)"
                        r"|wetin be di time)"
                        r"( for me| where i am)?", low):
        return None
    try:
        import pytz as _p
        now = _charlie_now()
        here = now.strftime('%-I:%M%p').lower().replace(':00', '')
        zone = str(now.tzinfo).split('/')[-1].replace('_', ' ')
        bits = [here + " here in " + zone]
        for nm, tz in (("Freetown", "Africa/Freetown"), ("Nairobi", "Africa/Nairobi")):
            if nm.lower() in zone.lower():
                continue
            t = now.astimezone(_p.timezone(tz))
            bits.append(t.strftime('%-I:%M%p').lower().replace(':00', '') + " " + nm)
        return "Na " + ", ".join(bits) + "."
    except Exception:
        return None


def _instant_conversion(text):
    """"what is 2000 leones in dollars" - answered from the rate table, no model call."""
    import re as _r
    t = (text or '').lower().strip()
    if not _r.search(r'\b(in|to|worth|equal|convert)\b', t) or len(t) > 90:
        return None
    if _r.search(r'\b(paid|bought|cost|buy|log|save)\b', t):
        return None
    words = {'leones?': 'SLE', 'sle': 'SLE', 'shillings?': 'KES', 'kes': 'KES', 'bob': 'KES',
             r'ghana(?:ian)?\s*(?:money|cedis?)?': 'GHS', r'kenyan?\s*money': 'KES',
             r'nigerian?\s*money': 'NGN', r'salone\s*money': 'SLE', r'sierra\s*leone\s*money': 'SLE',
             r'south\s*african?\s*money': 'ZAR', r'rwandan?\s*money': 'RWF',
             'cedis?': 'GHS', 'ghs': 'GHS', 'naira': 'NGN', 'ngn': 'NGN', 'rands?': 'ZAR',
             'zar': 'ZAR', 'dirhams?': 'AED', 'aed': 'AED', 'dollars?': 'USD', 'usd': 'USD',
             'bucks': 'USD', 'pounds?': 'GBP', 'gbp': 'GBP', 'euros?': 'EUR', 'eur': 'EUR',
             'francs?': 'RWF', 'rwf': 'RWF', 'rupees?': 'INR', 'yen': 'JPY', 'yuan': 'CNY'}
    m = _r.search(r'(?:^|[^0-9.])(\d[\d,]{0,12}(?:\.\d{1,2})?)\s*([a-z]{2,12})', t)
    if not m:
        return None
    amt = float(m.group(1).replace(',', ''))
    frm = None
    for pat, code in words.items():
        if _r.fullmatch(pat, m.group(2)):
            frm = code
            break
    if not frm and len(m.group(2)) == 3:
        frm = m.group(2).upper()
    if not frm:
        return None
    to = 'USD'
    rest = t[m.end():]
    for pat, code in words.items():
        if _r.search(r'\b(?:in|to)\b[^a-z]{0,6}' + pat + r'\b', rest):
            to = code
            break
    r1, s1, d1 = _fx_rate(frm)
    r2, _s2, _d2 = _fx_rate(to)
    if not r1 or not r2:
        return None
    val = amt * r1 / r2
    pretty = ("{:,.2f}".format(val) if val < 1000 else "{:,.0f}".format(val))
    return ("CONVERSION (already worked out, just say it): " +
            "{:,.0f}".format(amt) + " " + frm + " is about " + pretty + " " + to +
            " at 1 " + frm + " = $" + ("%.5f" % r1) + ", " + str(d1) + ".")


@app.get("/api/fitness/goals")
@require_password
def list_goals():
    try:
        from datetime import timedelta as _td
        now = _charlie_now().replace(tzinfo=None)
        goals = db.query("SELECT * FROM fitness_goals ORDER BY per DESC, id") or []
        out = []
        for g in goals:
            st = _goal_state(g)
            week = []
            for i in range(6, -1, -1):
                d0 = now - _td(days=i)
                day = d0.strftime('%Y-%m-%d')
                nm = ['Mon','Tue','Wed','Thu','Fri','Sat','Sun'][d0.weekday()]
                r = db.query("SELECT COALESCE(SUM(amount),0) AS n FROM goal_log WHERE goal_id=? AND done_on=?",
                             (g['id'], day))
                exc = bool(db.query("SELECT id FROM goal_excused WHERE day=?", (day,)))
                week.append({"day": nm, "date": day, "done": (r[0]['n'] if r else 0),
                             "target_day": (not g.get('days')) or nm in (g.get('days') or ''),
                             "excused": exc})
            badges = db.query("SELECT badge, day, amount FROM goal_badges WHERE goal_id=? ORDER BY day DESC LIMIT 5",
                              (g['id'],)) or []
            out.append({**g, "state": st, "week": week, "badges": badges})
        return {"status": "success", "goals": out}
    except Exception as e:
        return {"error": str(e)}, 400


