@app.post("/api/sports/teams")
@require_password
def sports_add_team():
    """Follow or unfollow a team."""
    try:
        d = request.get_json() or {}
        nm = (d.get('team') or '').strip()
        if not nm:
            return {"error": "needs a team"}, 400
        if d.get('remove'):
            db.execute("DELETE FROM followed_teams WHERE LOWER(team) = LOWER(?)", (nm,))
        else:
            db.execute("""INSERT OR IGNORE INTO followed_teams (team, league, sport)
                          VALUES (?,?,?)""", (nm, d.get('league') or '', d.get('sport') or ''))
        return {"status": "success",
                "teams": [r['team'] for r in (db.query(
                    "SELECT team FROM followed_teams WHERE active = 1 ORDER BY team") or [])]}
    except Exception as e:
        return {"error": str(e)}, 400


@app.post("/api/tasks/group")
@require_password
def group_tasks():
    """Look at the open board and say what belongs together. Suggests only."""
    try:
        import json as _j, re as _r
        tasks = db.query("""SELECT id, title, description, venture_id, due_date, source
                            FROM tasks
                            WHERE status NOT IN ('done','cancelled','completed')
                            ORDER BY created_at DESC LIMIT 60""") or []
        if len(tasks) < 2:
            return {"status": "success", "suggestions": [],
                    "note": "Not enough on the board to group yet."}

        ventures = {r['id']: r['name'] for r in (db.query(
            "SELECT id, name FROM ventures WHERE COALESCE(active,1)=1") or [])}

        lines = []
        for t in tasks:
            v = ventures.get(t.get('venture_id'))
            lines.append(str(t['id']) + ". " + str(t['title'])[:90]
                         + (" [" + v + "]" if v else " [no venture]"))

        prompt = (
            "These are the open tasks on one person's board. They were added from "
            "different places at different times, so related work is scattered.\n\n"
            + "\n".join(lines)
            + "\n\nHis ventures and projects: " + ", ".join(ventures.values())
            + "\n\nFind THREE kinds of thing, and nothing else:\n"
            "1. GROUP - several tasks that are clearly one piece of work. Say which "
            "venture if one fits, or name the piece of work.\n"
            "2. DUPLICATE - two tasks that are the same thing worded differently.\n"
            "3. ASSIGN - a task with no venture that clearly belongs to one.\n\n"
            "Only say something when you are confident. Two unrelated tasks that both "
            "mention a person are NOT a group. If nothing is clear, return an empty list.\n\n"
            "Reply with ONLY a JSON array, no other text:\n"
            '[{"kind":"group","label":"FundiConnect launch","venture":"FundiConnect",'
            '"task_ids":[3,7,12],"why":"all the vetting and pilot work"},\n'
            ' {"kind":"duplicate","label":"Call Ravi","task_ids":[4,19],'
            '"why":"same call, worded twice"},\n'
            ' {"kind":"assign","label":"Vet the first 20 fundis","venture":"FundiConnect",'
            '"task_ids":[3],"why":"clearly FundiConnect work"}]')

        import google.genai as genai
        client = genai.Client()
        resp = gemini_guard() or note_gemini_call() or _ask_gemini(client, prompt=prompt)
        note_gemini_tokens(resp)
        raw = (resp.text or '').strip()
        raw = _r.sub(r'^```(?:json)?|```$', '', raw, flags=_r.M).strip()
        m = _r.search(r'\[[\s\S]*\]', raw)
        if not m:
            return {"status": "success", "suggestions": [],
                    "note": "Nothing stood out as belonging together."}
        try:
            found = _j.loads(m.group(0))
        except Exception:
            return {"status": "success", "suggestions": [],
                    "note": "Could not read the suggestions."}

        by_id = {t['id']: t for t in tasks}
        out = []
        for f in found[:8]:
            ids = [i for i in (f.get('task_ids') or []) if i in by_id]
            if len(ids) < (2 if f.get('kind') in ('group', 'duplicate') else 1):
                continue
            out.append({
                "kind": f.get('kind'),
                "label": str(f.get('label') or '')[:70],
                "venture": f.get('venture'),
                "why": str(f.get('why') or '')[:110],
                "task_ids": ids,
                "titles": [str(by_id[i]['title'])[:70] for i in ids],
            })
        # a task already inside a group does not need its own assign line
        _in_group = set()
        for x in out:
            if x['kind'] in ('group', 'duplicate'):
                _in_group.update(x['task_ids'])
        out = [x for x in out
               if x['kind'] != 'assign' or not set(x['task_ids']) & _in_group]
        order = {'duplicate': 0, 'group': 1, 'assign': 2}
        out.sort(key=lambda x: order.get(x['kind'], 9))
        return {"status": "success", "suggestions": out,
                "note": ("" if out else "Nothing stood out as belonging together.")}
    except Exception as e:
        return {"error": str(e)}, 400


@app.post("/api/tasks/group/apply")
@require_password
def group_apply():
    """Apply only what he ticked."""
    try:
        d = request.get_json() or {}
        picks = d.get('apply') or []
        grouped = merged = assigned = 0
        for p in picks:
            kind = p.get('kind')
            ids = [int(i) for i in (p.get('task_ids') or [])]
            if not ids:
                continue
            vid = None
            if p.get('venture'):
                v = db.query("SELECT id FROM ventures WHERE LOWER(name) = LOWER(?)",
                             (p['venture'],))
                vid = v[0]['id'] if v else None

            if kind in ('group', 'assign'):
                for i in ids:
                    if vid:
                        db.execute("UPDATE tasks SET venture_id = ? WHERE id = ?", (vid, i))
                    if kind == 'group' and p.get('label'):
                        db.execute("UPDATE tasks SET tags = ? WHERE id = ?",
                                   (str(p['label'])[:60], i))
                grouped += len(ids) if kind == 'group' else 0
                assigned += len(ids) if kind == 'assign' else 0

            elif kind == 'duplicate' and len(ids) > 1:
                keep = min(ids)
                for i in ids:
                    if i != keep:
                        db.execute("UPDATE tasks SET status = 'cancelled', "
                                   "notes = COALESCE(notes,'') || ' (merged into #' || ? || ')' "
                                   "WHERE id = ?", (keep, i))
                        merged += 1
        return {"status": "success", "grouped": grouped,
                "merged": merged, "assigned": assigned}
    except Exception as e:
        return {"error": str(e)}, 400


@app.post("/api/projects/think")
@require_password
def project_think():
    """Her honest read on an idea, and the phases. Saves nothing."""
    try:
        d = request.get_json() or {}
        idea = (d.get('idea') or '').strip()
        if len(idea) < 8:
            return {"error": "tell me a bit more about it"}, 400
        existing = [r['name'] for r in (db.query(
            "SELECT name FROM ventures WHERE COALESCE(active,1)=1") or [])]
        prompt = (
            "Charlie wants to build this:\n\n" + idea[:1200] + "\n\n"
            "He already runs: " + ", ".join(existing) + ".\n\n"
            "Give him your honest read in three short parts:\n"
            "1. THE TRUTH - is this crowded, is there a real edge, what would make it "
            "worth doing. Two or three sentences. Be straight with him; if it is a bad "
            "idea say so.\n"
            "2. THE PHASES - four to six phases of actual work, in order. One line each.\n"
            "3. THE FIRST THING - the single thing to do first, and why.\n\n"
            "Plain English. No jargon, no hype. Reply as plain text with those three "
            "headings.")
        import google.genai as genai
        client = genai.Client()
        resp = gemini_guard() or note_gemini_call() or _ask_gemini(client, prompt=prompt)
        note_gemini_tokens(resp)
        return {"status": "success", "thinking": (resp.text or '').strip()}
    except Exception as e:
        return {"error": str(e)}, 400


@app.post("/api/projects/create")
@require_password
def project_create():
    """Make the project, and propose tasks. Nothing lands on the board yet."""
    try:
        import json as _j, re as _r
        d = request.get_json() or {}
        name = (d.get('name') or '').strip()
        about = (d.get('about') or '').strip()
        plan = (d.get('plan') or '').strip()
        if not name:
            return {"error": "it needs a name"}, 400

        dupe = db.query("SELECT id FROM ventures WHERE LOWER(name) = LOWER(?)", (name,))
        if dupe:
            pid = dupe[0]['id']
            made = False
        else:
            db.execute("""INSERT INTO ventures (name, description, type, stage, status,
                                                active, created_at)
                          VALUES (?, ?, 'project', 'idea', 'active', 1, CURRENT_TIMESTAMP)""",
                       (name, about or plan[:400]))
            pid = db.query("SELECT id FROM ventures WHERE LOWER(name) = LOWER(?)",
                           (name,))[0]['id']
            made = True

        proposed = []
        if plan or about:
            prompt = (
                "This is a project Charlie is starting: " + name + "\n\n"
                + (plan or about)[:2000] + "\n\n"
                "Turn this into the actual tasks. Rules:\n"
                "- Between 4 and 10 tasks, each one a real piece of work he could start\n"
                "- Each title under 70 characters, starting with a verb\n"
                "- In the order he should do them\n"
                "- No vague ones like 'plan the project' or 'do research'\n"
                "- Nothing that is really a phase heading\n\n"
                'Reply with ONLY a JSON array:\n'
                '[{"title":"Map the first 20 fundis in Freetown","why":"nothing works '
                'without supply"}]')
            import google.genai as genai
            client = genai.Client()
            resp = gemini_guard() or note_gemini_call() or _ask_gemini(client, prompt=prompt)
            note_gemini_tokens(resp)
            raw = _r.sub(r'^```(?:json)?|```$', '', (resp.text or '').strip(), flags=_r.M)
            m = _r.search(r'\[[\s\S]*\]', raw)
            if m:
                try:
                    for t in _j.loads(m.group(0))[:10]:
                        ttl = str(t.get('title') or '').strip()[:90]
                        if len(ttl) > 5:
                            proposed.append({"title": ttl,
                                             "why": str(t.get('why') or '')[:110]})
                except Exception:
                    pass

        # keep them so he can tick them later - they are not tasks yet
        for t in proposed:
            try:
                if not db.query("SELECT id FROM proposed_tasks WHERE venture_id = ? "
                                "AND title = ? AND status = 'waiting'", (pid, t['title'])):
                    db.execute("INSERT INTO proposed_tasks (venture_id, title, why) "
                               "VALUES (?, ?, ?)", (pid, t['title'], t.get('why') or ''))
            except Exception:
                pass
        return {"status": "success", "project_id": pid, "name": name,
                "created": made, "proposed": proposed}
    except Exception as e:
        return {"error": str(e)}, 400


@app.post("/api/projects/accept")
@require_password
def project_accept():
    """Only the tasks he ticked."""
    try:
        d = request.get_json() or {}
        pid = d.get('project_id')
        tasks = d.get('tasks') or []
        if not pid or not tasks:
            return {"error": "nothing to add"}, 400
        made = 0
        for t in tasks:
            ttl = str(t.get('title') or '').strip()[:90]
            if len(ttl) < 4:
                continue
            if db.query("SELECT id FROM tasks WHERE title = ? AND venture_id = ?", (ttl, pid)):
                continue
            db.execute("""INSERT INTO tasks (title, description, status, priority,
                                             venture_id, source, created_at, updated_at)
                          VALUES (?, ?, 'pending', 'medium', ?, 'from_ami',
                                  CURRENT_TIMESTAMP, CURRENT_TIMESTAMP)""",
                       (ttl, str(t.get('why') or '')[:200], pid))
            made += 1
        return {"status": "success", "added": made}
    except Exception as e:
        return {"error": str(e)}, 400


@app.get("/api/projects/<int:pid>/board")
@require_password
def project_board(pid):
    """One project: what it is, and everything on it."""
    try:
        v = db.query("SELECT * FROM ventures WHERE id = ?", (pid,))
        if not v:
            return {"error": "no such project"}, 404
        rows = db.query("""SELECT id, title, status, priority, due_date, tags, source
                           FROM tasks WHERE venture_id = ?
                           ORDER BY CASE status WHEN 'in_progress' THEN 0
                                                WHEN 'pending' THEN 1 ELSE 2 END,
                                    COALESCE(due_date, '9999')""", (pid,)) or []
        DONE = ('done', 'completed', 'complete')
        return {"status": "success",
                "project": {k: v[0].get(k) for k in
                            ('id', 'name', 'description', 'stage', 'status', 'next_action')},
                "tasks": rows,
                "counts": {"open": len([r for r in rows if r['status'] not in DONE]),
                           "done": len([r for r in rows if r['status'] in DONE]),
                           "total": len(rows)}}
    except Exception as e:
        return {"error": str(e)}, 400


