@app.get("/api/money/<int:pid>/quiet")
@require_password
def money_gone_quiet(pid):
    """Agreed a while back, nothing paid, nothing said. Finished and
    unbilled, or stalled - either way he should know."""
    try:
        ids = _all_under(pid)
        inlist = ",".join(str(i) for i in ids)
        rows = db.query("""SELECT q.id, q.what, q.amount, q.agreed_on, q.created_at,
                                  p.name,
                                  (SELECT COUNT(*) FROM job_payments y
                                   WHERE y.quote_id = q.id) AS payments,
                                  (SELECT MAX(paid_on) FROM job_payments y2
                                   WHERE y2.person_id = q.person_id) AS last_paid
                           FROM job_quotes q
                           JOIN job_people p ON p.id = q.person_id
                           WHERE q.venture_id IN (""" + inlist + """)
                             AND COALESCE(q.status,'agreed') NOT IN ('done','cancelled')
                           ORDER BY q.id""") or []
        from datetime import datetime as _dq
        today = _dq.now()
        quiet = []
        for r in rows:
            when = str(r.get('agreed_on') or r.get('created_at') or '')[:10]
            if not when:
                continue
            try:
                days = (today - _dq.strptime(when, '%Y-%m-%d')).days
            except Exception:
                continue
            if days >= 45 and not (r['payments'] or 0):
                quiet.append({"quote_id": r['id'], "who": r['name'], "what": r['what'],
                              "amount": r['amount'], "agreed": when, "days": days})
        return {"status": "success", "quiet": quiet}
    except Exception as e:
        return {"error": str(e)}, 400


@app.get("/api/money/<int:pid>/report.pdf")
@require_password
def money_report_pdf(pid):
    """The same report, as something he can send on WhatsApp."""
    try:
        from flask import send_file
        import io as _io
        from reportlab.lib.pagesizes import A4
        from reportlab.lib.units import mm
        from reportlab.pdfgen import canvas as _canvas

        v = db.query("SELECT name FROM ventures WHERE id = ?", (pid,))
        title = v[0]['name'] if v else 'Job'
        people, materials = _money_for(pid)
        quoted = sum(p['quoted'] for p in people)
        paid = sum(p['paid'] for p in people)
        cur = _job_currency(pid)

        buf = _io.BytesIO()
        c = _canvas.Canvas(buf, pagesize=A4)
        W, Hh = A4
        y = Hh - 25 * mm

        c.setFont("Helvetica-Bold", 17)
        c.drawString(20 * mm, y, title)
        y -= 7 * mm
        from datetime import datetime as _dr
        c.setFont("Helvetica", 9)
        c.setFillGray(0.45)
        c.drawString(20 * mm, y, "Where the money stands, " + _dr.now().strftime('%-d %B %Y'))
        c.setFillGray(0)
        y -= 12 * mm

        c.setFont("Helvetica", 11)
        for label, val in (("Quoted in total", quoted),
                           ("Paid out", paid),
                           ("Materials", materials),
                           ("Still owed", quoted - paid)):
            c.drawString(20 * mm, y, label)
            c.drawRightString(W - 20 * mm, y, _money_line(val, cur))
            y -= 6.5 * mm
        y -= 5 * mm

        c.setFont("Helvetica-Bold", 12)
        c.drawString(20 * mm, y, "Who is owed what")
        y -= 7 * mm
        c.setFont("Helvetica", 10)
        for p in sorted(people, key=lambda x: -x['owed']):
            if not (p['quoted'] or p['paid']):
                continue
            if y < 35 * mm:
                c.showPage(); y = Hh - 25 * mm; c.setFont("Helvetica", 10)
            c.drawString(22 * mm, y,
                         p['name'] + ((" - " + p['trade']) if p['trade'] else ""))
            c.drawRightString(W - 20 * mm, y,
                              "owed " + "{:,.0f}".format(p['owed']))
            y -= 5 * mm
            c.setFillGray(0.45)
            c.setFont("Helvetica", 8.5)
            c.drawString(26 * mm, y, "quoted " + "{:,.0f}".format(p['quoted'])
                         + ", paid " + "{:,.0f}".format(p['paid']))
            c.setFillGray(0)
            c.setFont("Helvetica", 10)
            y -= 7 * mm

        moved = [(p, d) for p in people for d in p['drift']]
        if moved:
            y -= 4 * mm
            c.setFont("Helvetica-Bold", 12)
            c.drawString(20 * mm, y, "Where the estimates moved")
            y -= 7 * mm
            c.setFont("Helvetica", 9.5)
            for p, d in moved:
                if y < 30 * mm:
                    c.showPage(); y = Hh - 25 * mm; c.setFont("Helvetica", 9.5)
                first = float(d['first'] or 0)
                now = float(d['now'] or 0)
                pct = (" (" + "{:+.0f}".format((now - first) / first * 100) + "%)") if first else ""
                c.drawString(22 * mm, y, p['name'] + " - " + str(d['what']) + ": "
                             + "{:,.0f}".format(first) + " then " + "{:,.0f}".format(now) + pct)
                y -= 5 * mm
                if d['why']:
                    c.setFillGray(0.45)
                    c.setFont("Helvetica", 8.5)
                    c.drawString(26 * mm, y, str(d['why'])[:95])
                    c.setFillGray(0)
                    c.setFont("Helvetica", 9.5)
                    y -= 6 * mm

        c.showPage()
        c.save()
        buf.seek(0)
        safe = "".join(ch for ch in title if ch.isalnum() or ch in " -_").strip()[:40]
        return send_file(buf, mimetype='application/pdf', as_attachment=True,
                         download_name=(safe or "job") + " money.pdf")
    except Exception as e:
        return {"error": str(e)}, 400


def _spend_under(pid):
    """Everything this project and its children have quoted and spent."""
    ids = _all_under(pid)
    inlist = ",".join(str(i) for i in ids)
    q = (db.query("SELECT COALESCE(SUM(amount),0) AS s FROM job_quotes "
                  "WHERE venture_id IN (" + inlist + ")") or [{"s": 0}])[0]['s'] or 0
    p = (db.query("SELECT COALESCE(SUM(amount),0) AS s FROM job_payments "
                  "WHERE venture_id IN (" + inlist + ")") or [{"s": 0}])[0]['s'] or 0
    st = (db.query("SELECT COALESCE(SUM(r.amount),0) AS s FROM stipend_runs r "
                   "JOIN stipend_terms t ON t.id = r.term_id "
                   "WHERE t.venture_id IN (" + inlist + ")") or [{"s": 0}])[0]['s'] or 0
    comm = (db.query("SELECT COALESCE(SUM(sp.monthly),0) * 4 AS s FROM stipend_people sp "
                     "JOIN stipend_terms t ON t.id = sp.term_id "
                     "WHERE t.venture_id IN (" + inlist + ") "
                     "AND COALESCE(sp.active,1) = 1") or [{"s": 0}])[0]['s'] or 0
    return (float(q) + float(comm), float(p) + float(st))


@app.get("/api/money/level")
@require_password
def money_level():
    """What sits at this level, with everything beneath it counted in.
    No parent given means the top: GII, Personal, whatever he has."""
    try:
        parent = request.args.get('parent')
        if parent:
            pid = int(parent)
            kids = db.query("""SELECT id, name, type, stage FROM ventures
                               WHERE parent_id = ? AND COALESCE(active,1) = 1
                               ORDER BY name""", (pid,)) or []
            here = db.query("SELECT id, name FROM ventures WHERE id = ?", (pid,))
            crumbs, walk = [], pid
            for _ in range(6):
                r = db.query("SELECT id, name, parent_id FROM ventures WHERE id = ?", (walk,))
                if not r:
                    break
                crumbs.insert(0, {"id": r[0]['id'], "name": r[0]['name']})
                if not r[0].get('parent_id'):
                    break
                walk = r[0]['parent_id']
        else:
            kids = db.query("""SELECT id, name, type, stage FROM ventures
                               WHERE parent_id IS NULL AND COALESCE(active,1) = 1
                               ORDER BY name""") or []
            here, crumbs, pid = None, [], None

        rows = []
        for k in kids:
            quoted, spent = _spend_under(k['id'])
            has_kids = bool(db.query("SELECT id FROM ventures WHERE parent_id = ? "
                                     "AND COALESCE(active,1) = 1 LIMIT 1", (k['id'],)))
            rows.append({"id": k['id'], "name": k['name'],
                         "stage": k.get('stage') or '',
                         "quoted": round(quoted, 2), "spent": round(spent, 2),
                         "owed": round(quoted - spent, 2),
                         "goes_deeper": has_kids,
                         "currency": _job_currency(k['id'])})

        # anyone working directly at this level, not on a child
        people = []
        if pid:
            ps, _mat = _money_for(pid)
            people = [p for p in ps if p['quoted'] or p['paid']]

        tq = sum(r['quoted'] for r in rows) + sum(p['quoted'] for p in people)
        ts = sum(r['spent'] for r in rows) + sum(p['paid'] for p in people)
        return {"status": "success",
                "here": ({"id": here[0]['id'], "name": here[0]['name']} if here else None),
                "trail": crumbs,
                "under": rows,
                "people": people,
                "currency": (_job_currency(pid) if pid else 'USD'),
                "totals": {"quoted": round(tq, 2), "spent": round(ts, 2),
                           "owed": round(tq - ts, 2)}}
    except Exception as e:
        return {"error": str(e)}, 400


@app.post("/api/fitness/plan-from-words")
@require_password
def fitness_plan_from_words():
    """He says what he wants. She builds it from what he has."""
    try:
        import json as _jf, re as _rf
        d = request.get_json() or {}
        asked = (d.get('prompt') or d.get('text') or '').strip()
        if len(asked) < 8:
            return {"error": "tell me what you want"}, 400

        mine = db.query("""SELECT id, name, area, kind, equipment, knee_load, knee_twist
                           FROM exercises ORDER BY area, name""") or []
        if not mine:
            return {"error": "no exercises in the library yet"}, 400

        lib = []
        for e in mine:
            bits = [str(e['id']) + ". " + str(e['name'])]
            if e.get('area'):
                bits.append("(" + str(e['area'])
                            + ((", " + str(e['kind'])) if e.get('kind') else "") + ")")
            if str(e.get('knee_load') or '').lower() in ('high', 'heavy'):
                bits.append("[hard on knees]")
            if str(e.get('knee_twist') or '').lower() in ('yes', 'high', 'true', '1'):
                bits.append("[twists the knee]")
            lib.append(" ".join(bits))

        # how long, and which days - read from what he wrote, with sane defaults
        weeks = 4
        m = _rf.search(r"(\d{1,2})\s*(week|month)", asked.lower())
        if m:
            weeks = int(m.group(1)) * (4 if m.group(2) == 'month' else 1)
        weeks = max(1, min(weeks, 26))

        days = [dn for dn in ('monday', 'tuesday', 'wednesday', 'thursday',
                              'friday', 'saturday', 'sunday') if dn in asked.lower()]
        if not days:
            days = ['monday', 'wednesday', 'friday']

        prompt = (
            "Build Charlie a training plan. These are the ONLY exercises he has - "
            "use nothing else, and refer to each by its number:\n\n"
            + "\n".join(lib) + "\n\n"
            "What he asked for:\n" + asked[:700] + "\n\n"
            "Rules:\n"
            "- " + str(weeks) + " weeks, training on: " + ", ".join(days) + "\n"
            "- His knees are bad. Nothing marked [hard on knees] or [twists the knee] "
            "unless he explicitly asked for it.\n"
            "- If two training days run back to back, make the first one lighter.\n"
            "- 5 to 8 movements a day including any warmup and cooldown he asked for.\n"
            "- Vary it across the weeks - do not repeat the same day over and over.\n"
            "- Sets and reps that suit a man in his forties coming back steadily.\n\n"
            'Reply with ONLY a JSON object:\n'
            '{"name":"short plan name",'
            '"days":[{"week":1,"day":"monday","items":['
            '{"id":12,"sets":3,"reps":"10","note":"slow on the way down"}]}]}'
        )

        import google.genai as genai
        client = genai.Client()
        resp = gemini_guard() or note_gemini_call() or _ask_gemini(client, prompt=prompt)
        note_gemini_tokens(resp)
        raw = _rf.sub(r'^```(?:json)?|```$', '', (resp.text or '').strip(), flags=_rf.M)
        mm = _rf.search(r'\{[\s\S]*\}', raw)
        if not mm:
            return {"error": "could not read the plan back"}, 400
        got = _jf.loads(mm.group(0))

        known = {e['id'] for e in mine}
        name = str(got.get('name') or 'Training plan')[:60]
        db.execute("""INSERT INTO fitness_plans (goal, weeks, days, started_on, status, notes)
                      VALUES (?, ?, ?, date('now'), 'active', ?)""",
                   (name, weeks, len(days), asked[:400]))
        pr = db.query("SELECT id FROM fitness_plans ORDER BY id DESC LIMIT 1")
        if not pr:
            return {"error": "the plan did not save"}, 400
        pid = pr[0]['id']

        made = 0
        for dayblock in (got.get('days') or []):
            wk = int(dayblock.get('week') or 1)
            dy = str(dayblock.get('day') or '')[:12].lower()
            for n, it in enumerate(dayblock.get('items') or []):
                try:
                    eid = int(it.get('id'))
                except Exception:
                    continue
                if eid not in known:
                    continue        # she invented one - skip it
                db.execute("""INSERT INTO plan_items (plan_id, day, exercise_id, target_sets,
                                                      target_reps, position, week, note)
                              VALUES (?, ?, ?, ?, ?, ?, ?, ?)""",
                           (pid, dy, eid, it.get('sets'), str(it.get('reps') or ''),
                            n, wk, str(it.get('note') or '')[:120]))
                made += 1

        if not made:
            db.execute("DELETE FROM fitness_plans WHERE id = ?", (pid,))
            return {"error": "nothing usable came back"}, 400

        return {"status": "success", "plan_id": pid, "name": name,
                "weeks": weeks, "days": days, "movements": made}
    except Exception as e:
        return {"error": str(e)}, 400


