def _is_for_work(pid):
    """Did he agree work with them, or lend them money? An unpaid agreement
    means he owes them - not the other way round."""
    try:
        ks = {str(k['kind']) for k in (db.query(
            "SELECT DISTINCT kind FROM ledger_entries WHERE person_id = ?", (pid,)) or [])}
        return ('agreed' in ks) and not (ks & {'lent'})
    except Exception:
        return False


def _ledger_balance(person_id, currency=None):
    """What stands between him and this person. Positive means they owe him."""
    rows = db.query("""SELECT kind, who_owes, amount, currency, status
                       FROM ledger_entries WHERE person_id = ?""", (person_id,)) or []
    by_cur = {}
    for r in rows:
        # a gift is not a debt, and finished work is settled
        if (str(r.get('status')) in ('forgiven', 'done')
                or str(r.get('kind')) == 'gift'):
            continue
        cur = (r.get('currency') or 'USD').upper()[:4]
        amt = float(r.get('amount') or 0)
        k = str(r.get('kind') or '')
        side = str(r.get('who_owes') or 'them')
        b = by_cur.setdefault(cur, {"they_owe": 0.0, "he_owes": 0.0})
        if side == 'me':
            # money he took, or something they bought for him
            if k in ('borrowed', 'bought', 'agreed'):
                b['he_owes'] += amt
            elif k in ('repaid', 'paid'):
                b['he_owes'] -= amt
        else:
            # work they agreed to do, or money he lent them
            if k in ('agreed', 'lent'):
                b['they_owe'] += amt
            elif k in ('paid', 'repaid'):
                b['they_owe'] -= amt
            elif k == 'bought':
                b['he_owes'] += amt
    out = {}
    for cur, b in by_cur.items():
        net = round(b['they_owe'] - b['he_owes'], 2)
        out[cur] = {"they_owe": round(b['they_owe'], 2),
                    "he_owes": round(b['he_owes'], 2),
                    "net": net,
                    "usd": _in_usd(abs(net), cur)}
    return out


@app.get("/api/ledger/people")
@require_password
def ledger_people():
    """Everyone he has money with. The live ones first, and only as many as
    a screen can usefully hold - the rest come when he asks for them."""
    try:
        lim = min(int(request.args.get('limit') or 40), 200)
        want_quiet = str(request.args.get('quiet') or '') == '1'
        hunt = (request.args.get('q') or '').strip()

        sql = ("SELECT id, name, what_they_do FROM ledger_people "
               "WHERE COALESCE(active,1) = 1 ")
        args = []
        if hunt:
            sql += "AND LOWER(name) LIKE LOWER(?) "
            args.append('%' + hunt + '%')
        sql += "ORDER BY name"
        rows = db.query(sql, tuple(args)) or []

        live, quiet = [], []
        for r in rows:
            bal = _ledger_balance(r['id'])
            has = any(abs(b['net']) > 0.01 for b in bal.values()) if bal else False
            entry = {"id": r['id'], "name": r['name'],
                     "what_they_do": r.get('what_they_do') or '',
                     "for_work": (_is_for_work(r['id']) if has else False),
                     "balances": (bal if has else {}), "quiet": not has}
            (live if has else quiet).append(entry)

        live.sort(key=lambda x: -max(
            (abs(b.get('usd') or b.get('net') or 0) for b in x['balances'].values()),
            default=0))

        if want_quiet:
            shown = quiet[:lim]
            return {"status": "success", "people": shown,
                    "more": max(0, len(quiet) - len(shown)), "showing": "quiet"}

        shown = live[:lim]
        return {"status": "success", "people": shown,
                "more": max(0, len(live) - len(shown)),
                "quiet_count": len(quiet)}
    except Exception as e:
        return {"error": str(e)}, 400


