@app.get("/api/ledger/overview")
@require_password
def ledger_overview():
    """Who owes him, who he owes, across everything."""
    try:
        people = db.query("""SELECT id, name, what_they_do FROM ledger_people
                             WHERE COALESCE(active,1) = 1""") or []
        owed_to_him, he_owes = [], []
        for p in people:
            for cur, b in (_ledger_balance(p['id']) or {}).items():
                if abs(b['net']) < 0.01:
                    continue
                row = {"id": p['id'], "name": p['name'],
                       "what_they_do": p.get('what_they_do') or '',
                       "amount": abs(b['net']), "currency": cur,
                       "usd": b['usd'],
                       "for_work": _is_for_work(p['id'])}
                # an unpaid agreement for work is something HE owes
                _his = (b['net'] < 0) or (b['net'] > 0 and row['for_work'])
                (he_owes if _his else owed_to_him).append(row)
        owed_to_him.sort(key=lambda x: -(x['usd'] or x['amount']))
        he_owes.sort(key=lambda x: -(x['usd'] or x['amount']))
        return {"status": "success",
                "they_owe_him": owed_to_him,
                "he_owes": he_owes,
                "totals_usd": {
                    "they_owe": round(sum(x['usd'] or 0 for x in owed_to_him), 2),
                    "he_owes": round(sum(x['usd'] or 0 for x in he_owes), 2)}}
    except Exception as e:
        return {"error": str(e)}, 400


@app.get("/api/ledger/loans")
@require_password
def ledger_loans():
    """Only the lending, both ways, with what is left and when it clears."""
    try:
        from datetime import datetime as _dn
        rows = db.query("""SELECT e.*, p.name FROM ledger_entries e
                           JOIN ledger_people p ON p.id = e.person_id
                           WHERE e.kind IN ('lent','borrowed','bought')
                           ORDER BY e.happened_on DESC""") or []
        out = []
        # repayments clear the oldest loan first, and only once
        _pot = {}
        for r in sorted(rows, key=lambda x: str(x.get('happened_on') or '')):
            _k = (r['person_id'], (r['currency'] or 'USD'))
            if _k not in _pot:
                _pot[_k] = float((db.query(
                    """SELECT COALESCE(SUM(amount),0) AS s FROM ledger_entries
                       WHERE person_id = ? AND kind = 'repaid'
                         AND COALESCE(currency,'USD') = ?""",
                    (r['person_id'], r['currency'] or 'USD')) or [{"s": 0}])[0]['s'] or 0)
            principal = float(r['amount'] or 0)
            back = min(_pot[_k], principal)
            _pot[_k] -= back
            left = round(principal - back, 2)
            per = float(r.get('repay_amount') or 0)
            months = (int(left / per) + (1 if left % per else 0)) if per > 0 and left > 0 else None
            out.append({
                "id": r['id'], "who": r['name'],
                "direction": ("he lent" if r['kind'] == 'lent'
                              else ("they bought for him" if r['kind'] == 'bought'
                                    else "he borrowed")),
                "principal": principal, "repaid": round(float(back), 2),
                "left": max(0, left), "currency": r['currency'],
                "usd_left": _in_usd(max(0, left), r['currency']),
                "note": r.get('note') or '', "since": r.get('happened_on'),
                "repay_amount": r.get('repay_amount'),
                "repay_every": r.get('repay_every'),
                "months_to_clear": months,
                "interest_rate": r.get('interest_rate'),
                "status": r.get('status')})
        return {"status": "success", "loans": out}
    except Exception as e:
        return {"error": str(e)}, 400


@app.get("/api/ledger/project/<int:vid>")
@require_password
def ledger_project(vid):
    """What this job has cost, who is on it, and where estimates moved."""
    try:
        ids = _all_under(vid)
        inlist = ",".join(str(i) for i in ids)
        v = db.query("SELECT name FROM ventures WHERE id = ?", (vid,))
        rows = db.query("""SELECT e.*, p.name FROM ledger_entries e
                           LEFT JOIN ledger_people p ON p.id = e.person_id
                           WHERE e.venture_id IN (""" + inlist + """)
                           ORDER BY e.happened_on""") or []
        folk, agreed, paid, bought = {}, 0.0, 0.0, 0.0
        stuff = []
        cur = 'USD'
        for r in rows:
            cur = r.get('currency') or cur
            amt = float(r.get('amount') or 0)
            if not r.get('person_id'):
                # a thing to buy, not somebody to pay
                stuff.append({"what": r.get('note') or 'item',
                              "amount": amt, "currency": r.get('currency'),
                              "got_it": (r['kind'] == 'paid'),
                              "on": r.get('happened_on')})
                if r['kind'] == 'agreed':
                    agreed += amt
                elif r['kind'] in ('paid', 'bought'):
                    bought += amt
                continue
            who = r.get('name') or 'someone'
            f = folk.setdefault(who, {"agreed": 0.0, "paid": 0.0, "bought": 0.0})
            if str(r.get('status')) == 'forgiven':
                continue
            if r['kind'] == 'agreed':
                f['agreed'] += amt; agreed += amt
            elif r['kind'] == 'paid':
                f['paid'] += amt; paid += amt
            elif r['kind'] == 'bought':
                f['bought'] += amt; bought += amt
        moved = db.query("""SELECT c.was, c.now_is, c.why, e.note, p.name
                            FROM ledger_changes c
                            JOIN ledger_entries e ON e.id = c.entry_id
                            LEFT JOIN ledger_people p ON p.id = e.person_id
                            WHERE e.venture_id IN (""" + inlist + """)
                            ORDER BY c.id DESC LIMIT 12""") or []
        return {"status": "success",
                "project": (v[0]['name'] if v else ''),
                "currency": cur,
                "materials": stuff,
                "people": [{"name": k, "agreed": round(x['agreed'], 2),
                            "paid": round(x['paid'], 2), "bought": round(x['bought'], 2),
                            "owed": round(x['agreed'] - x['paid'], 2)}
                           for k, x in sorted(folk.items())],
                "totals": {"agreed": round(agreed, 2), "paid": round(paid, 2),
                           "bought": round(bought, 2),
                           "spent": round(paid + bought, 2),
                           "owed": round(agreed - paid, 2),
                           "usd_spent": _in_usd(paid + bought, cur)},
                "moved": moved}
    except Exception as e:
        return {"error": str(e)}, 400


def _money_s(amount, currency):
    """1,500 SLE (~61 USD). Plain when it is already dollars."""
    cur = (currency or 'USD').upper()[:4]
    base = "{:,.0f}".format(float(amount or 0)) + " " + cur
    if cur == 'USD':
        return base
    u = _in_usd(amount, cur)
    return base + ((" (~" + "{:,.0f}".format(u) + " USD)") if u else "")


def _report_person(pid):
    """One account, the way a statement reads."""
    p = db.query("SELECT * FROM ledger_people WHERE id = ?", (pid,))
    if not p:
        return None, []
    rows = db.query("""SELECT e.*, v.name AS project FROM ledger_entries e
                       LEFT JOIN ventures v ON v.id = e.venture_id
                       WHERE e.person_id = ?
                       ORDER BY e.happened_on, e.id""", (pid,)) or []
    name = p[0]['name']
    L = [name]
    if p[0].get('what_they_do'):
        L.append(str(p[0]['what_they_do']))
    L.append("")
    bal = _ledger_balance(pid)
    for cur, b in bal.items():
        if abs(b['net']) < 0.01:
            continue
        if b['net'] > 0:
            L.append(name + " owes you " + _money_s(b['net'], cur))
        else:
            L.append("You owe " + name + " " + _money_s(-b['net'], cur))
    _gifts = [r for r in rows if str(r.get('kind')) == 'gift']
    if _gifts:
        L.append("")
        L.append("Gifts (not owed either way)")
        for g in _gifts:
            _d = ("you gave" if str(g.get('who_owes')) == 'them' else "they gave you")
            L.append("  " + str(g.get('happened_on') or '')[:10] + "  " + _d + " "
                     + _money_s(g['amount'], g['currency'])
                     + (("  - " + str(g['note'])[:40]) if g.get('note') else ""))
    L.append("")
    L.append("Every line")
    WORDS = {'agreed': 'agreed', 'paid': 'you paid', 'bought': 'they bought',
             'lent': 'you lent', 'borrowed': 'you borrowed', 'repaid': 'repaid',
             'forgiven': 'written off', 'gift': 'a gift'}
    for r in rows:
        tag = "  " + str(r.get('happened_on') or '')[:10] + "  "
        tag += (WORDS.get(r['kind'], r['kind']) + " ").ljust(14)
        tag += "{:,.0f}".format(float(r['amount'] or 0)).rjust(10) + " " + (r['currency'] or '')
        if r.get('note'):
            tag += "   " + str(r['note'])[:44]
        if str(r.get('status')) == 'forgiven':
            tag += "   [written off]"
        L.append(tag)
    moved = db.query("""SELECT c.was, c.now_is, c.why, e.note FROM ledger_changes c
                        JOIN ledger_entries e ON e.id = c.entry_id
                        WHERE e.person_id = ? ORDER BY c.id""", (pid,)) or []
    if moved:
        L.append("")
        L.append("Where the figure moved")
        for m in moved:
            was, now = float(m['was'] or 0), float(m['now_is'] or 0)
            pct = (" (" + "{:+.0f}".format((now - was) / was * 100) + "%)") if was else ""
            L.append("  " + str(m.get('note') or 'the work') + ": "
                     + "{:,.0f}".format(was) + " then " + "{:,.0f}".format(now) + pct
                     + (("  - " + str(m['why'])) if m.get('why') else ""))
    return name, L


def _report_project(vid):
    """A job, for whoever is asking about it."""
    d = ledger_project(vid)
    if isinstance(d, tuple):
        d = d[0]
    if not isinstance(d, dict) or d.get('error'):
        return None, []
    cur = d.get('currency') or 'USD'
    t = d.get('totals') or {}
    L = [str(d.get('project') or 'The job')]
    from datetime import datetime as _dr
    L.append("Where the money stands, " + _dr.now().strftime('%-d %B %Y'))
    L.append("")
    L.append("Agreed in total   " + _money_s(t.get('agreed'), cur))
    L.append("Paid out          " + _money_s(t.get('paid'), cur))
    if t.get('bought'):
        L.append("Bought for it     " + _money_s(t.get('bought'), cur))
    L.append("Still owed        " + _money_s(t.get('owed'), cur))
    L.append("")
    L.append("Who is on it")
    L.append("  " + "".ljust(22) + "agreed".rjust(11) + "paid".rjust(11)
             + "owed".rjust(11))
    for p in sorted(d.get('people') or [], key=lambda x: -x['owed']):
        if not (p['agreed'] or p['paid'] or p['bought']):
            continue
        L.append("  " + str(p["name"])[:21].ljust(22)
                 + "{:,.0f}".format(p["agreed"]).rjust(11)
                 + "{:,.0f}".format(p["paid"]).rjust(11)
                 + "{:,.0f}".format(p["owed"]).rjust(11))
    _tt = d.get("totals") or {}
    L.append("  " + "everyone".ljust(22)
             + "{:,.0f}".format(_tt.get("agreed") or 0).rjust(11)
             + "{:,.0f}".format(_tt.get("paid") or 0).rjust(11)
             + "{:,.0f}".format(_tt.get("owed") or 0).rjust(11))
    if d.get('materials'):
        L.append("")
        L.append("Things to buy")
        _ms = 0.0
        for m in d['materials']:
            _ms += float(m['amount'] or 0)
            L.append("  " + str(m['what'])[:30].ljust(31)
                     + "{:,.0f}".format(float(m['amount'] or 0)).rjust(11)
                     + ("   got it" if m.get('got_it') else "   still to get"))
        L.append("  " + "all of it".ljust(31) + "{:,.0f}".format(_ms).rjust(11))

    if d.get('moved'):
        L.append("")
        L.append("Where the estimates moved")
        for m in d['moved']:
            was, now = float(m['was'] or 0), float(m['now_is'] or 0)
            pct = (" (" + "{:+.0f}".format((now - was) / was * 100) + "%)") if was else ""
            L.append("  " + str(m.get('name') or '') + " - " + str(m.get('note') or '')
                     + ": " + "{:,.0f}".format(was) + " then " + "{:,.0f}".format(now) + pct
                     + (("  - " + str(m['why'])) if m.get('why') else ""))
    return str(d.get('project') or 'job'), L


def _report_loans():
    d = ledger_loans()
    if isinstance(d, tuple):
        d = d[0]
    L = ["Lending", ""]
    out_, in_ = [], []
    for l in (d.get('loans') or []):
        (out_ if l['direction'] == 'he lent' else in_).append(l)
    if out_:
        L.append("Money you lent")
        for l in out_:
            s = "  " + str(l['who'])[:20].ljust(21) + _money_s(l['principal'], l['currency'])
            s += "   left " + "{:,.0f}".format(l['left'])
            if l.get('months_to_clear'):
                s += "   clears in " + str(l['months_to_clear']) + " months"
            L.append(s)
            if l.get('note'):
                L.append("      " + str(l['note'])[:60])
        L.append("")
    if in_:
        L.append("Money you took")
        for l in in_:
            s = "  " + str(l['who'])[:20].ljust(21) + _money_s(l['principal'], l['currency'])
            s += "   left " + "{:,.0f}".format(l['left'])
            L.append(s)
            if l.get('note'):
                L.append("      " + str(l['note'])[:60])
    if not out_ and not in_:
        L.append("Nothing lent either way.")
    return "Lending", L


def _report_all():
    d = ledger_overview()
    if isinstance(d, tuple):
        d = d[0]
    t = d.get('totals_usd') or {}
    from datetime import datetime as _dr
    L = ["Where everything stands", _dr.now().strftime('%-d %B %Y'), ""]
    L.append("Owed to you     ~" + "{:,.0f}".format(t.get('they_owe') or 0) + " USD")
    L.append("You owe         ~" + "{:,.0f}".format(t.get('he_owes') or 0) + " USD")
    L.append("")
    if d.get('they_owe_him'):
        L.append("They owe you")
        for x in d['they_owe_him']:
            L.append("  " + str(x['name'])[:22].ljust(23) + _money_s(x['amount'], x['currency']))
    if d.get('he_owes'):
        L.append("")
        L.append("You owe them")
        for x in d['he_owes']:
            L.append("  " + str(x['name'])[:22].ljust(23) + _money_s(x['amount'], x['currency']))
    try:
        _fx = db.query("SELECT currency, COALESCE(fetched_on, as_of) AS as_of "
                       "FROM fx_rates WHERE COALESCE(fetched_on, as_of) IS NOT NULL "
                       "ORDER BY as_of DESC LIMIT 1") or []
        if _fx:
            L.append("")
            L.append("USD figures use rates set " + str(_fx[0]['as_of'])[:10] + ".")
    except Exception:
        pass
    return "Everything", L


@app.get("/api/ledger/report")
@require_password
def ledger_report():
    """person / project / loans / all - as text he can read or send."""
    try:
        what = (request.args.get('what') or 'all').lower()
        if what == 'person':
            title, L = _report_person(int(request.args.get('id')))
        elif what == 'project':
            title, L = _report_project(int(request.args.get('id')))
        elif what == 'loans':
            title, L = _report_loans()
        else:
            title, L = _report_all()
        if not L:
            return {"error": "nothing to report on"}, 404
        return {"status": "success", "title": title, "report": "\n".join(L)}
    except Exception as e:
        return {"error": str(e)}, 400


@app.get("/api/ledger/report.pdf")
@require_password
def ledger_report_pdf():
    """The same, as something to send on WhatsApp."""
    try:
        from flask import send_file
        import io as _io
        from reportlab.lib.pagesizes import A4
        from reportlab.lib.units import mm
        from reportlab.pdfgen import canvas as _cv

        what = (request.args.get('what') or 'all').lower()
        if what == 'person':
            title, L = _report_person(int(request.args.get('id')))
        elif what == 'project':
            title, L = _report_project(int(request.args.get('id')))
        elif what == 'loans':
            title, L = _report_loans()
        else:
            title, L = _report_all()
        if not L:
            return {"error": "nothing to report on"}, 404

        buf = _io.BytesIO()
        c = _cv.Canvas(buf, pagesize=A4)
        W, Hh = A4
        y = Hh - 24 * mm
        c.setFont("Helvetica-Bold", 16)
        c.drawString(20 * mm, y, str(L[0])[:60])
        y -= 10 * mm
        for line in L[1:]:
            if y < 22 * mm:
                c.showPage(); y = Hh - 24 * mm
            s = str(line)
            if not s.strip():
                y -= 3.5 * mm
                continue
            indented = s.startswith('  ')
            heading = (not indented) and len(s) < 46 and not any(ch.isdigit() for ch in s[:4])
            c.setFont("Helvetica-Bold" if heading else "Helvetica",
                      11 if heading else 9.5)
            if indented:
                c.setFillGray(0.2)
            c.drawString((24 if indented else 20) * mm, y, s.strip()[:104])
            c.setFillGray(0)
            y -= (6.5 if heading else 5) * mm
        c.showPage(); c.save(); buf.seek(0)
        safe = "".join(ch for ch in str(title) if ch.isalnum() or ch in " -_").strip()[:40]
        return send_file(buf, mimetype='application/pdf', as_attachment=True,
                         download_name=(safe or "money") + ".pdf")
    except Exception as e:
        return {"error": str(e)}, 400


