@app.get("/api/ledger/account/<int:pid>")
@require_password
def ledger_account(pid):
    """Two hands: what came in, what went back, and the difference.

    Gifts show on the incoming side so he can see them, but they never
    count toward what he owes.
    """
    try:
        p = db.query("SELECT * FROM ledger_people WHERE id = ?", (pid,))
        if not p:
            return {"error": "no such person"}, 404
        _lim = min(int(request.args.get('limit') or 40), 200)
        rows = db.query("""SELECT e.*, v.name AS project FROM ledger_entries e
                           LEFT JOIN ventures v ON v.id = e.venture_id
                           WHERE e.person_id = ?
                           ORDER BY e.happened_on DESC, e.id DESC LIMIT ?""",
                        (pid, _lim)) or []
        total = (db.query("SELECT COUNT(*) AS n FROM ledger_entries WHERE person_id = ?",
                          (pid,)) or [{"n": 0}])[0]['n']

        came_in, went_back, gifts = [], [], []
        for r in rows:
            _rc = (db.query("SELECT COUNT(*) AS n FROM ledger_receipts WHERE entry_id = ?",
                            (r['id'],)) or [{"n": 0}])[0]['n']
            line = {"id": r['id'], "receipts": _rc,
                    "kind": r['kind'], "amount": r['amount'],
                    "currency": r['currency'], "usd": _in_usd(r['amount'], r['currency']),
                    "note": r.get('note') or '', "on": r.get('happened_on'),
                    "how_sent": r.get('how_sent') or '', "project": r.get('project'),
                    "status": r.get('status'),
                    "moved": (db.query("""SELECT was, now_is, why FROM ledger_changes
                                          WHERE entry_id = ? ORDER BY id""",
                                       (r['id'],)) or [])}
            k = str(r['kind'])
            if k == 'gift':
                gifts.append(line)
            elif k in ('paid', 'repaid'):
                went_back.append(line)
            else:
                came_in.append(line)

        bal = _ledger_balance(pid)
        return {"status": "success",
                "person": {"id": p[0]['id'], "name": p[0]['name'],
                           "what_they_do": p[0].get('what_they_do') or '',
                           "phone": p[0].get('phone') or ''},
                "balances": bal,
                "came_in": came_in,
                "went_back": went_back,
                "gifts": gifts,
                "older_not_shown": max(0, total - len(rows)),
                "ways": HOW_SENT}
    except Exception as e:
        return {"error": str(e)}, 400


@app.get("/api/ledger/job/<int:vid>")
@require_password
def ledger_job(vid):
    """The job's figures, plus who is on it so he can tap through."""
    try:
        d = ledger_project(vid)
        if isinstance(d, tuple):
            d = d[0]
        if not isinstance(d, dict) or d.get('error'):
            return {"error": "could not read that job"}, 400
        ids = _all_under(vid)
        inlist = ",".join(str(i) for i in ids)
        folk = db.query("""SELECT DISTINCT p.id, p.name, p.what_they_do
                           FROM ledger_entries e
                           JOIN ledger_people p ON p.id = e.person_id
                           WHERE e.venture_id IN (""" + inlist + """)
                           ORDER BY p.name""") or []
        out = []
        for f in folk:
            # what is owed ON THIS JOB, not everything he owes them everywhere
            here = db.query("""SELECT kind, amount, currency, status FROM ledger_entries
                               WHERE person_id = ? AND venture_id IN (""" + inlist + """)""",
                            (f['id'],)) or []
            agreed = paid = 0.0
            cur = ''
            for e in here:
                if str(e.get('status')) in ('forgiven', 'done'):
                    continue
                cur = cur or (e.get('currency') or '')
                amt = float(e.get('amount') or 0)
                if e['kind'] == 'agreed':
                    agreed += amt
                elif e['kind'] in ('paid', 'repaid'):
                    paid += amt
            everywhere = _ledger_balance(f['id'])
            first = list(everywhere.items())[0] if everywhere else None
            out.append({"id": f['id'], "name": f['name'],
                        "what_they_do": f.get('what_they_do') or '',
                        "for_work": _is_for_work(f['id']),
                        "currency": cur or (first[0] if first else ''),
                        "net": round(agreed - paid, 2),
                        "agreed_here": round(agreed, 2),
                        "paid_here": round(paid, 2),
                        "net_everywhere": (first[1]['net'] if first else 0)})
        title, L = _report_project(vid)
        _v = db.query("SELECT name, description, parent_id FROM ventures WHERE id = ?",
                      (vid,))
        _pa = None
        if _v and _v[0].get('parent_id'):
            _pr = db.query("SELECT name FROM ventures WHERE id = ?", (_v[0]['parent_id'],))
            _pa = _pr[0]['name'] if _pr else None
        return {"status": "success", "project": d.get('project'),
                "name": (_v[0]['name'] if _v else ''),
                "note": (_v[0].get('description') if _v else '') or '',
                "part_of": _pa,
                "totals": d.get('totals'), "materials": d.get('materials') or [],
                "people": out, "report": "\n".join(L) if L else ''}
    except Exception as e:
        return {"error": str(e)}, 400


@app.post("/api/ledger/job/<int:vid>/work")
@require_password
def ledger_job_add_work(vid):
    """Somebody is doing something on this job for an agreed amount.

    Takes either an existing person_id, or a name - in which case they are
    added to the book first, matched against his contacts.
    """
    try:
        from datetime import datetime as _dj
        d = request.get_json() or {}
        pid = d.get('person_id')
        if not pid:
            name = (d.get('name') or '').strip()[:60]
            if len(name) < 2:
                return {"error": "who is doing it?"}, 400
            found = db.query("SELECT id FROM ledger_people WHERE LOWER(name) = LOWER(?)",
                             (name,))
            if found:
                pid = found[0]['id']
            else:
                cid, full = _find_contact(name)
                db.execute("""INSERT INTO ledger_people (name, what_they_do, contact_id)
                              VALUES (?, ?, ?)""",
                           (full or name, (d.get('what_they_do') or '')[:40], cid))
                r = db.query("SELECT id FROM ledger_people ORDER BY id DESC LIMIT 1")
                if not r:
                    return {"error": "could not add them"}, 400
                pid = r[0]['id']

        amount = float(d.get('amount') or 0)
        what = (d.get('what') or d.get('note') or '').strip()[:160]
        if amount <= 0 or len(what) < 2:
            return {"error": "what was agreed, and for how much?"}, 400

        cur = (d.get('currency') or '').upper()[:4]
        if not cur:
            cur = _job_currency(vid)
        db.execute("""INSERT INTO ledger_entries (person_id, venture_id, kind, who_owes,
                      amount, currency, note, happened_on)
                      VALUES (?, ?, 'agreed', 'them', ?, ?, ?, ?)""",
                   (int(pid), vid, amount, cur, what,
                    d.get('happened_on') or _dj.now().strftime('%Y-%m-%d')))
        if not db.query("""SELECT id FROM ledger_entries WHERE person_id = ?
                           AND venture_id = ? AND note = ? ORDER BY id DESC LIMIT 1""",
                        (pid, vid, what)):
            return {"error": "it did not save"}, 400
        return {"status": "success", "person_id": pid}
    except Exception as e:
        return {"error": str(e)}, 400


