# ===========================================================================
# Krio, as something she teaches while they talk.
#
# Three jobs:
#   * a lesson when he asks for one, a topic at a time
#   * translation either way - "how do you say thank you in Krio"
#   * and the one that matters daily: any Krio word he does not know, he
#     can ask about mid-conversation and she explains it. She only answers
#     when she actually recognises the word, so an ordinary English
#     question is never mistaken for a Krio one.
# ===========================================================================

_KRIO_SET = {"done": False}

_KRIO_TOPICS = ("greetings", "replies", "meeting", "farewells", "politeness",
                "understanding", "language", "shopping", "trouble",
                "feelings", "celebrations", "everyday", "asking", "numbers",
                "words")


def _krio_ready():
    if _KRIO_SET["done"]:
        return
    db.execute("CREATE TABLE IF NOT EXISTS krio_phrases ("
               "id INTEGER PRIMARY KEY AUTOINCREMENT, english TEXT, "
               "krio TEXT, sounds TEXT, topic TEXT, variants TEXT, "
               "check_it INTEGER DEFAULT 0, times INTEGER DEFAULT 0, "
               "said_on TEXT)")
    _KRIO_SET["done"] = True
    # anything missing goes in - so new phrases can be added later
    try:
        have = set()
        for r in (db.query("SELECT english, krio FROM krio_phrases") or []):
            have.add(((r.get("english") or "").lower(),
                      (r.get("krio") or "").lower()))
    except Exception:
        return
    n = 0
    for en, kr, snd, top, chk, alt in _KRIO_PHRASES:
        if (en.lower(), kr.lower()) in have:
            continue
        try:
            db.execute("INSERT INTO krio_phrases (english, krio, sounds, "
                       "topic, variants, check_it) VALUES (?,?,?,?,?,?)",
                       (en, kr, snd, top, alt, chk))
            n += 1
        except Exception:
            pass
    if n:
        print("KRIO: %d phrases written down" % n, flush=True)


def _krio_line(r, full=False):
    out = "**%s** - %s" % (r.get("krio"), r.get("english"))
    if r.get("sounds"):
        out += "  (%s)" % r["sounds"]
    if full and r.get("variants"):
        out += "\n   Yu kin se am so too: " + str(r["variants"])
    if r.get("check_it"):
        out += "   [needs checking]"
    return out


def _krio_mark(r):
    from datetime import datetime as _dt
    try:
        db.execute("UPDATE krio_phrases SET times = COALESCE(times,0) + 1, "
                   "said_on = ? WHERE id = ?",
                   (_dt.now().strftime("%Y-%m-%d"), r["id"]))
    except Exception:
        pass


def _krio_topic(topic, n=12, teachable=True):
    _krio_ready()
    sql = "SELECT * FROM krio_phrases WHERE topic = ?"
    if teachable:
        sql += " AND COALESCE(check_it,0) = 0"
    return db.query(sql + " ORDER BY id LIMIT ?", (topic, n)) or []


def _krio_fold(s):
    """ɛ and ɔ are hard to type, so matching ignores them."""
    return ((s or "").lower().replace("ɛ", "e").replace("ɔ", "o")
            .replace("ŋ", "n").strip())


def _krio_look(word):
    """Anything that looks like this word, however he spelt it."""
    _krio_ready()
    w = _krio_fold((word or "").strip().strip("?.!,'\""))
    if len(w) < 2:
        return []
    rows = db.query("SELECT * FROM krio_phrases") or []
    exact, inside = [], []
    for r in rows:
        k = _krio_fold(r.get("krio"))
        v = _krio_fold(r.get("variants"))
        e = _krio_fold(r.get("english"))
        if k == w or e == w:
            exact.append(r)
        elif w in k or w in v or (len(w) > 3 and w in e):
            inside.append(r)
    out = exact + inside
    out.sort(key=lambda r: (r.get("check_it") or 0))
    return out[:4]


def _krio_in_proverb(word):
    w = (word or "").strip().lower()
    if len(w) < 3:
        return None
    try:
        rows = db.query("SELECT * FROM proverbs WHERE COALESCE(adult,0) = 0 "
                        "AND (LOWER(krio) LIKE ? OR LOWER(plain) LIKE ?) "
                        "LIMIT 1", ("%" + w + "%", "%" + w + "%"))
        return rows[0] if rows else None
    except Exception:
        return None


def _krio_explain(text):
    """He met a word and does not know it. Only answers when she knows it."""
    import re
    low = (text or "").strip().lower()
    m = re.search(r"(?:wetin na|wetin|what does|what do|what is|whats|"
                  r"what's|meaning of|explain|how fɔ use)\s+"
                  r"[\"']?([a-zɔɛŋ' -]{2,30}?)[\"']?\s*"
                  r"(?:mean|means|min|stand for|in krio|na krio)?\s*[?.!]*$",
                  low)
    if not m:
        return None
    want = m.group(1).strip()
    want = re.sub(r"^(di|da|dat|the|this|that|a|an|word|phrase)\s+", "", want)
    if not want:
        return None

    rows = _krio_look(want)
    # a loose match inside an example should not beat the real word
    exact = [r for r in rows if _krio_fold(r.get("krio")) == _krio_fold(want)]
    if rows and not exact:
        try:
            spot = [r for r in _kd_look(want)
                    if _krio_fold(r.get("krio")) == _krio_fold(want)]
        except Exception:
            spot = []
        if spot:
            return ("\n\n".join(_kd_say(r) for r in spot[:3])
                    + "\n\n_(from di dictionary - A Dictionary of Sierra "
                      "Leone Krio)_")
    if rows:
        out = []
        for r in rows[:2]:
            _krio_mark(r)
            out.append(_krio_line(r, full=True))
        return "\n\n".join(out) + "\n\n_(from yu own list)_"

    # then the dictionary - thousands of words, but the plain spelling
    try:
        hits = _kd_look(want)
    except Exception as e:
        print("KRIO DICT: lookup failed -", repr(e), flush=True)
        hits = []
    if hits:
        body = "\n\n".join(_kd_say(r) for r in hits[:3])
        return body + "\n\n_(from di dictionary - A Dictionary of Sierra " \
                      "Leone Krio)_"

    # last, it may be one word out of a proverb
    p = _krio_in_proverb(want)
    if p:
        return ("'%s' na from dis one:\n\n%s\n\n%s"
                % (want, p.get("krio"), p.get("english") or ""))
    return None


def _krio_how(text):
    """How do you say ___ in Krio.  The thing he wants said may itself
    contain the word Krio, so the match runs to the last 'in krio'."""
    import re
    low = (text or "").strip().lower()
    m = re.search(r"(?:how (?:do|du|can|fɔ) (?:yu|you|i|we) say|how fɔ say|"
                  r"aw yu se|wetin na|say)\s*[,:]?\s*(.{2,60})"
                  r"\s*(?:in|na|pan)\s+krio\b\s*[?.!]*$", low)
    if not m:
        return None
    _krio_ready()
    want = m.group(1).strip().strip(" ?.!,'\"“”‘’")
    if not want:
        return None
    rows = db.query("SELECT * FROM krio_phrases WHERE LOWER(english) LIKE ? "
                    "ORDER BY COALESCE(check_it,0), LENGTH(english), id "
                    "LIMIT 4", ("%" + want + "%",)) or []
    if not rows:
        bits = [w for w in re.sub(r"[^a-z ]", " ", want).split()
                if len(w) > 2 and w not in ("the", "and", "for", "you",
                                            "want", "how", "say")]
        if bits:
            rows = db.query(
                "SELECT * FROM krio_phrases WHERE LOWER(english) LIKE ? "
                "ORDER BY COALESCE(check_it,0), LENGTH(english), id LIMIT 3",
                ("%" + bits[-1] + "%",)) or []
    if not rows:
        try:
            hits = _kd_english(want)
        except Exception:
            hits = []
        if hits:
            return ("\n\n".join(_kd_say(r, short=True) for r in hits[:3])
                    + "\n\n_(from di dictionary)_")
        return ("A no get '%s' pan mi list yet, bo. If yu find di Krio, "
                "tell mi en a go keep am." % want)
    out = []
    for r in rows:
        _krio_mark(r)
        out.append(_krio_line(r, full=True))
    return "\n\n".join(out)


def _krio_lesson(topic=None):
    """A topic at a time, finished with a proverb."""
    _krio_ready()
    import random
    if not topic:
        done = db.query("SELECT topic, COUNT(*) n FROM krio_phrases "
                        "WHERE COALESCE(check_it,0) = 0 AND "
                        "COALESCE(times,0) = 0 GROUP BY topic "
                        "ORDER BY n DESC") or []
        topic = (done[0]["topic"] if done
                 else random.choice(list(_KRIO_TOPICS)))
    rows = _krio_topic(topic, 6)
    if not rows:
        return None
    out = "Krio fɔ tide - %s:\n" % topic
    for r in rows:
        out += "\n- " + _krio_line(r)
        _krio_mark(r)
    try:
        p = _prov_pick()
        if p:
            _prov_used(p[0])
            out += "\n\nEn wan proverb:\n\n" + _prov_say(p[0])
    except Exception:
        pass
    out += "\n\nAsk mi wetin any word mean en a go tell yu."
    return out


def _krio_tip():
    """One phrase, for the morning word, if it is ever wanted there."""
    _krio_ready()
    rows = db.query("SELECT * FROM krio_phrases WHERE COALESCE(check_it,0)=0 "
                    "ORDER BY COALESCE(times,0), COALESCE(said_on,''), "
                    "RANDOM() LIMIT 1") or []
    if not rows:
        return ""
    _krio_mark(rows[0])
    return "Krio fɔ tide: " + _krio_line(rows[0])


def _krio_from_chat(text):
    """Teaching Krio. Stands back for proverbs, and for anything she does
    not actually recognise."""
    import re
    low = (text or "").strip().lower()
    if not low:
        return None
    if re.search(r"\b(proverb|proverbs|saying|parable)\b", low):
        return None

    out = _krio_how(text)
    if out:
        return out

    out = _krio_explain(text)
    if out:
        return out

    if not re.search(r"\bkrio\b", low):
        return None

    for topic in _KRIO_TOPICS:
        if re.search(r"\b" + topic.split()[0] + r"\b", low):
            rows = _krio_topic(topic, 14)
            if rows:
                for r in rows:
                    _krio_mark(r)
                return ("Krio - %s:\n\n" % topic +
                        "\n\n".join(_krio_line(r, full=True) for r in rows))

    if re.search(r"\b(teach|learn|lan|lesson|practice|practise|study|word|"
                 r"words|phrase|phrases|speak|tɔk|help me)\b", low):
        return _krio_lesson()
    return None


@app.get("/api/krio")
@require_password
def krio_list():
    try:
        _krio_ready()
        topic = (request.args.get("topic") or "").strip().lower()
        q = (request.args.get("q") or "").strip().lower()
        if topic:
            rows = db.query("SELECT * FROM krio_phrases WHERE topic = ? "
                            "ORDER BY id", (topic,)) or []
        elif q:
            rows = db.query("SELECT * FROM krio_phrases WHERE LOWER(english) "
                            "LIKE ? OR LOWER(krio) LIKE ? OR LOWER(variants) "
                            "LIKE ? ORDER BY topic, id",
                            ("%" + q + "%",) * 3) or []
        else:
            rows = db.query("SELECT * FROM krio_phrases ORDER BY topic, id") \
                or []
        return {"status": "success", "count": len(rows),
                "topics": list(_KRIO_TOPICS),
                "phrases": [dict(r) for r in rows]}
    except Exception as e:
        return {"error": str(e)}, 400




# ===========================================================================
# Taking a dose back out.
#
# "I didn't take it on the 13th, I took it on the 11th" has to remove a row
# and write another. She said "a clear am" and cleared nothing, which is
# worse than refusing, because the next dose is counted off that date.
# ===========================================================================

_MED_NOT = (r"\b(no no|not|nɔto|no be|nɔ bi|didn'?t|didnt|never|wrong|"
            r"mistake|delete|remove|clear|cancel|undo|take out|tek out|"
            r"correct)\b")


def _med_days(text):
    """Every day he mentions, in the order he said them."""
    import re
    from datetime import datetime as _dt, timedelta as _td
    low = (text or "").lower()
    now = _dt.now()
    found = []

    for m in re.finditer(r"\b(\d{4})-(\d{1,2})-(\d{1,2})\b", low):
        try:
            found.append((m.start(), "%04d-%02d-%02d"
                          % tuple(int(x) for x in m.groups())))
        except Exception:
            pass
    for m in re.finditer(r"\byesterday\b|\byestaday\b|\byestade\b", low):
        found.append((m.start(), (now - _td(days=1)).strftime("%Y-%m-%d")))
    for m in re.finditer(r"\btoday\b|\btide\b", low):
        found.append((m.start(), now.strftime("%Y-%m-%d")))

    months = ("january february march april may june july august september "
              "october november december").split()
    for m in re.finditer(r"\b(\d{1,2})(?:st|nd|rd|th)?\s+(" +
                         "|".join(x[:3] for x in months) + r")[a-z]*", low):
        try:
            d = int(m.group(1))
            mo = [x[:3] for x in months].index(m.group(2)) + 1
            found.append((m.start(), _dt(now.year, mo, d)
                          .strftime("%Y-%m-%d")))
        except Exception:
            pass

    for m in re.finditer(r"\b(?:on|pan)?\s*(?:the|di)\s*(\d{1,2})"
                         r"\s*(?:st|nd|rd|th)\b|\bon\s+(\d{1,2})"
                         r"\s*(?:st|nd|rd|th)?\b", low):
        raw = m.group(1) or m.group(2)
        if not raw:
            continue
        try:
            day = int(raw)
            if not (1 <= day <= 31):
                continue
            y, mo = now.year, now.month
            if day > now.day:
                mo -= 1
                if mo < 1:
                    mo, y = 12, y - 1
            iso = _dt(y, mo, day).strftime("%Y-%m-%d")
        except Exception:
            continue
        if not any(abs(p - m.start()) < 4 and v == iso for p, v in found):
            found.append((m.start(), iso))

    seen, out = set(), []
    for pos, iso in sorted(found):
        if iso not in seen:
            seen.add(iso)
            out.append((pos, iso))
    return out


def _med_drop(m, day):
    try:
        rows = db.query("SELECT id FROM medication_log WHERE medication_id = ?"
                        " AND taken_on = ?", (m["id"], day)) or []
        if not rows:
            return 0
        db.execute("DELETE FROM medication_log WHERE medication_id = ? AND "
                   "taken_on = ?", (m["id"], day))
        return len(rows)
    except Exception as e:
        print("MEDS: could not take it out -", repr(e), flush=True)
        return None


def _med_fix(text):
    """Correcting what was written down. Runs before the writing does."""
    import re
    low = (text or "").strip().lower()
    if not low or not re.search(_MED_NOT, low):
        return None

    m = _med_find(low)
    if not m:
        if not re.search(_MED_ALL, low):
            return None
        meds = [x for x in _med_rows()
                if (x.get("schedule_kind") or "") == "interval"]
        if len(meds) != 1:
            return ("Which medicine, bo? Say di name en a go correct am.")
        m = meds[0]

    days = _med_days(low)
    if not days:
        return ("Which day should a take out? Say di date, bo.")

    neg = re.search(_MED_NOT, low)
    negpos = neg.start() if neg else -1

    bad, good = None, None
    if len(days) == 1:
        bad = days[0][1]
    else:
        after = [d for p, d in days if p > negpos]
        before = [d for p, d in days if p <= negpos]
        if after and before:
            bad, good = after[0], before[-1]
        elif len(days) >= 2:
            # "it was the 11th and not the 13th" - the last one is the wrong
            bad, good = days[-1][1], days[0][1]

    # he may have named the right day first and the wrong one after, or the
    # other way about; whichever is written down already is the one to drop
    have = set()
    try:
        for r in (db.query("SELECT taken_on FROM medication_log WHERE "
                           "medication_id = ?", (m["id"],)) or []):
            have.add(r.get("taken_on"))
    except Exception:
        pass
    if good and bad and good in have and bad not in have:
        bad, good = good, bad

    took = 0
    if bad:
        took = _med_drop(m, bad)
    wrote = False
    if good:
        wrote = _med_write(m, good) is True

    if took is None:
        return "A try fɔ take am out bɔt e nɔ wok. Try again, bo."

    bits = []
    if took:
        bits.append("A take out %s fɔ %s." % (m["name"], bad))
    elif bad:
        bits.append("A nɔ get %s write down fɔ %s - so natin fɔ take out."
                    % (m["name"], bad))
    if good and wrote:
        bits.append("A write am down fɔ %s." % good)
    elif good:
        bits.append("%s already de fɔ %s." % (m["name"], good))

    rows = db.query("SELECT taken_on FROM medication_log WHERE "
                    "medication_id = ? ORDER BY taken_on DESC LIMIT 1",
                    (m["id"],)) or []
    if rows and rows[0].get("taken_on"):
        last = rows[0]["taken_on"]
        nxt = _med_next(m, last)
        bits.append("Now di last one na %s.%s"
                    % (last, (" " + nxt) if nxt else ""))
    else:
        bits.append("Now a nɔ get any day write down fɔ am.")
    return " ".join(bits)


@app.delete("/api/medications/<int:mid>/taken")
@require_password
def medications_untaken(mid):
    try:
        d = request.get_json() or {}
        day = d.get("on") or request.args.get("on")
        if not day:
            return {"error": "which day?"}, 400
        rows = db.query("SELECT * FROM medications WHERE id = ?", (mid,))
        if not rows:
            return {"error": "no such medicine"}, 404
        n = _med_drop(rows[0], day)
        return {"status": "success", "removed": n, "on": day}
    except Exception as e:
        return {"error": str(e)}, 400

