# ===========================================================================
# The dictionary.
#
# A Dictionary of Sierra Leone Krio, ERIC ED012454, read off the scan. Any
# Krio word he meets, she can now say what it means - and she says where
# the answer came from, so he can tell the vetted phrases from a line out
# of an old book from something she made up herself.
#
# The scan loses ɛ and ɔ, so headwords here are the plain spelling. Good
# for meaning, not to be trusted for how a word is written: the 132
# phrases stay the teaching set.
# ===========================================================================

_KD_SET = {"done": False}
_KD_SOURCE = "A Dictionary of Sierra Leone Krio (ERIC ED012454)"


def _kd_ready():
    if _KD_SET["done"]:
        return
    db.execute("CREATE TABLE IF NOT EXISTS krio_book ("
               "id INTEGER PRIMARY KEY AUTOINCREMENT, krio TEXT, "
               "english TEXT, gloss TEXT, pos TEXT, example TEXT, "
               "source TEXT, times INTEGER DEFAULT 0)")
    try:
        db.execute("CREATE INDEX IF NOT EXISTS krio_book_word "
                   "ON krio_book (krio)")
    except Exception:
        pass
    _KD_SET["done"] = True
    try:
        have = db.query("SELECT COUNT(*) c FROM krio_book")
        if have and int(have[0]["c"]) > 0:
            return
    except Exception:
        return
    import json as _json
    try:
        rows = _json.loads(_KD_DATA)
    except Exception as e:
        print("KRIO DICT: could not read it -", repr(e), flush=True)
        return
    n = 0
    for r in rows:
        try:
            db.execute("INSERT INTO krio_book (krio, english, gloss, "
                       "pos, example, source) VALUES (?,?,?,?,?,?)",
                       (r.get("k"), r.get("e"), r.get("g"), r.get("p"),
                        r.get("x"), _KD_SOURCE))
            n += 1
        except Exception:
            pass
    print("KRIO DICT: %d words written down" % n, flush=True)


def _kd_say(r, short=False):
    out = "**%s**" % r.get("krio")
    if r.get("pos"):
        out += " (%s)" % r["pos"]
    meaning = r.get("gloss") or r.get("english") or ""
    if meaning:
        out += " - " + meaning
    if not short and r.get("example"):
        out += "\n   Lɛk dis: " + str(r["example"])
    return out


def _kd_look(word, n=4):
    """Fold ɛ and ɔ, try the whole word first, then what starts with it."""
    _kd_ready()
    w = _krio_fold((word or "").strip(" ?.!,'\""))
    if len(w) < 2:
        return []
    out, seen = [], set()
    for sql, args in (
            ("SELECT * FROM krio_book WHERE krio = ? LIMIT 6", (w,)),
            ("SELECT * FROM krio_book WHERE krio LIKE ? "
             "ORDER BY LENGTH(krio) LIMIT 6", (w + "%",)),
            ("SELECT * FROM krio_book WHERE LOWER(gloss) LIKE ? "
             "ORDER BY LENGTH(gloss) LIMIT 4", ("%" + w + "%",))):
        try:
            for r in (db.query(sql, args) or []):
                if r["id"] in seen:
                    continue
                seen.add(r["id"])
                out.append(r)
            if len(out) >= n:
                break
        except Exception:
            continue
    return out[:n]


def _kd_english(want, n=4):
    """The other way about - English in, Krio out."""
    _kd_ready()
    w = (want or "").strip().lower()
    if len(w) < 2:
        return []
    try:
        return db.query(
            "SELECT * FROM krio_book WHERE LOWER(gloss) = ? OR "
            "LOWER(english) = ? OR LOWER(gloss) LIKE ? "
            "ORDER BY (LOWER(gloss) = ?) DESC, LENGTH(gloss) LIMIT ?",
            (w, w, "%" + w + "%", w, n)) or []
    except Exception:
        return []


@app.get("/api/krio/dictionary")
@require_password
def krio_dictionary():
    try:
        _kd_ready()
        q = (request.args.get("q") or "").strip().lower()
        if not q:
            c = db.query("SELECT COUNT(*) c FROM krio_book")
            return {"status": "success", "words": (c[0]["c"] if c else 0),
                    "source": _KD_SOURCE}
        rows = _kd_look(q, 20) or _kd_english(q, 20)
        return {"status": "success", "count": len(rows),
                "source": _KD_SOURCE, "words": [dict(r) for r in rows]}
    except Exception as e:
        return {"error": str(e)}, 400

if __name__ == '__main__':
    app.run(debug=True, port=8000, use_reloader=False)